window.TEXTBOOK_TEXTS = Object.assign(window.TEXTBOOK_TEXTS || {}, {"hsk4a-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们好，欢迎来到中国留学！请把护照、签证和入学通知书给我。","pinyin":"Nǐmen hǎo, huānyíng láidào Zhōngguó liúxué! Qǐng bǎ hùzhào, qiānzhèng hé rùxué tōngzhīshū gěi wǒ.","speaker":"老师","vi":"Chào các em, chào mừng đến Trung Quốc du học! Hãy đưa hộ chiếu, visa và giấy báo nhập học cho cô."},{"hanzi":"好的。这是我们的证件和材料。","pinyin":"Hǎo de. Zhè shì wǒmen de zhèngjiàn hé cáiliào.","speaker":"白家月","vi":"Vâng ạ. Đây là giấy tờ và tài liệu của chúng em."},{"hanzi":"（几分钟后。）","pinyin":"(Jǐ fēnzhōng hòu.)","speaker":"Dẫn chuyện","vi":"(Vài phút sau.)"},{"hanzi":"办好了，这是你们的学生证，下周一开始上课。先试听两周，然后在网上选课。","pinyin":"Bànhǎo le, zhè shì nǐmen de xuéshengzhèng, xià Zhōuyī kāishǐ shàngkè. Xiān shìtīng liǎng zhōu, ránhòu zài wǎngshàng xuǎnkè.","speaker":"老师","vi":"Làm xong rồi, đây là thẻ sinh viên của các em, thứ Hai tuần sau bắt đầu lên lớp. Học thử trước hai tuần, sau đó chọn môn trên mạng."},{"hanzi":"谢谢老师。","pinyin":"Xièxie lǎoshī.","speaker":"白家月、陈天中","vi":"Cảm ơn cô ạ."},{"hanzi":"不客气，你们以后有任何问题都可以来找我。","pinyin":"Bú kèqi, nǐmen yǐhòu yǒu rènhé wèntí dōu kěyǐ lái zhǎo wǒ.","speaker":"老师","vi":"Không có gì, sau này các em có bất kỳ vấn đề gì đều có thể đến tìm cô."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài giáo viên nói \"办好了，这是你们的学生证\" (Làm xong rồi, đây là thẻ sinh viên của các em), còn hộ chiếu, visa và giấy báo nhập học là giấy tờ hai bạn nộp cho giáo viên.","options":["护照","学生证","签证","入学通知书"],"q":"老师为白家月和陈天中办好了什么证件？"},{"answerIdx":2,"explanation":"Trong bài giáo viên dặn \"下周一开始上课。先试听两周，然后在网上选课。\" (Thứ Hai tuần sau bắt đầu lên lớp. Học thử hai tuần trước, sau đó chọn môn học trên mạng).","options":["今天开始上课，在办公室选课","下个月开始上课，先选课再试听","下周一开始上课，先试听两周再在网上选课","下周三开始上课，让老师帮忙选课"],"q":"他们什么时候开始上课，怎么选课？"}],"scene":"在学院办公室，白家月和陈天中在办理入学手续。","sceneVi":"Tại văn phòng học viện, Bạch Gia Nguyệt và Trần Thiên Trung đang làm thủ tục nhập học."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你看，咱们的校园真大！有图书馆、体育馆、超市，还有好几个食堂。","pinyin":"Nǐ kàn, zánmen de xiàoyuán zhēn dà! Yǒu túshūguǎn, tǐyùguǎn, chāoshì, hái yǒu hǎojǐ gè shítáng.","speaker":"陈天中","vi":"Cậu xem, khuôn viên trường mình rộng thật đấy! Có thư viện, nhà thi đấu thể thao, siêu thị, còn có mấy nhà ăn nữa."},{"hanzi":"是啊，我觉得学校就像一座小城市，什么都有，方便极了。","pinyin":"Shì a, wǒ juéde xuéxiào jiù xiàng yí zuò xiǎo chéngshì, shénme dōu yǒu, fāngbiàn jíle.","speaker":"白家月","vi":"Đúng vậy, mình thấy trường học giống như một thành phố nhỏ vậy, cái gì cũng có, tiện lợi cực kỳ."},{"hanzi":"刚才老师说，咱们可以申请奖学金，你了解过吗？","pinyin":"Gāngcái lǎoshī shuō, zánmen kěyǐ shēnqǐng jiǎngxuéjīn, nǐ liǎojiě guo ma?","speaker":"陈天中","vi":"Lúc nãy cô giáo nói chúng ta có thể xin học bổng, cậu đã tìm hiểu qua chưa?"},{"hanzi":"我听说过一点儿，好像成绩好、表现好的学生都有机会获得奖学金。","pinyin":"Wǒ tīngshuō guo yìdiǎnr, hǎoxiàng chéngjì hǎo, biǎoxiàn hǎo de xuésheng dōu yǒu jīhuì huòdé jiǎngxuéjīn.","speaker":"白家月","vi":"Mình có nghe nói qua một chút, hình như sinh viên có thành tích tốt, biểu hiện tốt đều có cơ hội nhận được học bổng."},{"hanzi":"那太好了，要是申请到奖学金，就能减轻不少经济压力。","pinyin":"Nà tài hǎo le, yàoshi shēnqǐng dào jiǎngxuéjīn, jiù néng jiǎnqīng bùshǎo jīngjì yālì.","speaker":"陈天中","vi":"Thế thì tuyệt quá, nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế."},{"hanzi":"没错，我们一起加油吧！","pinyin":"Méicuò, wǒmen yìqǐ jiāyóu ba!","speaker":"白家月","vi":"Đúng vậy, chúng ta cùng cố gắng nhé!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我觉得学校就像一座小城市，什么都有，方便极了。\" (Mình cảm thấy trường học giống như một thành phố nhỏ vậy, cái gì cũng có, vô cùng tiện lợi).","options":["像一座小城市，什么都有，非常方便","虽然很大，但是食堂和超市太少了","环境很安静，不过离市区有点儿远","图书馆和体育馆都太旧了，不太方便"],"q":"白家月觉得他们的校园怎么样？"},{"answerIdx":3,"explanation":"Trong bài Trần Thiên Trung nói \"要是申请到奖学金，就能减轻不少经济压力。\" (Nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế).","options":["因为老师要求每个留学生都必须申请","因为他的成绩一直是全班第一名","因为学校给所有新生都发奖学金","因为申请到奖学金可以减轻不少经济压力"],"q":"陈天中为什么想申请奖学金？"}],"scene":"在大学校园，白家月和陈天中边逛边聊。","sceneVi":"Trong khuôn viên trường đại học, Bạch Gia Nguyệt và Trần Thiên Trung vừa đi dạo vừa trò chuyện."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"随着中国的发展，越来越多的外国学生来到中国的大学学习。","pinyin":"Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí.","speaker":"Đoạn văn","vi":"Cùng với sự phát triển của Trung Quốc, ngày càng có nhiều sinh viên nước ngoài đến học tập tại các trường đại học của Trung Quốc."},{"hanzi":"他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。","pinyin":"Tāmen kěyǐ xiān shàng yì nián de Zhōngwén kèchéng, ránhòu gēnjù zìjǐ de xìngqù hé xūyào xuǎnzé zhuānyè.","speaker":"Đoạn văn","vi":"Họ có thể học một năm khóa tiếng Trung trước, sau đó chọn chuyên ngành dựa theo sở thích và nhu cầu của bản thân."},{"hanzi":"除了读本科课程，他们还可以申请读硕士研究生或者博士研究生。","pinyin":"Chúle dú běnkē kèchéng, tāmen hái kěyǐ shēnqǐng dú shuòshì yánjiūshēng huòzhě bóshì yánjiūshēng.","speaker":"Đoạn văn","vi":"Ngoài học chương trình đại học, họ còn có thể đăng ký học thạc sĩ hoặc tiến sĩ."},{"hanzi":"在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。","pinyin":"Zài dàxué lǐ, wàiguó xuésheng kěyǐ hé Zhōngguó xuésheng yìqǐ xuéxí, zuò yánjiū, cānjiā xiàoyuán huódòng.","speaker":"Đoạn văn","vi":"Ở trường đại học, sinh viên nước ngoài có thể cùng sinh viên Trung Quốc học tập, làm nghiên cứu và tham gia các hoạt động trong khuôn viên trường."},{"hanzi":"通过这些交流，外国学生能更快地适应中国的大学生活。","pinyin":"Tōngguò zhèxiē jiāoliú, wàiguó xuésheng néng gèng kuài de shìyìng Zhōngguó de dàxué shēnghuó.","speaker":"Đoạn văn","vi":"Thông qua những sự giao lưu này, sinh viên nước ngoài có thể thích nghi nhanh hơn với cuộc sống đại học ở Trung Quốc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。\" (Họ có thể học khóa tiếng Trung một năm trước, sau đó chọn chuyên ngành dựa theo sở thích và nhu cầu của bản thân).","options":["完全由学校和老师帮他们决定","根据自己的兴趣和需要来选择","只能选择中文或者中国文化专业","必须和中国学生选择一样的专业"],"q":"上完一年的中文课程后，外国学生怎么选择专业？"},{"answerIdx":0,"explanation":"Trong bài có câu \"在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。通过这些交流，外国学生能更快地适应中国的大学生活。\" (Thông qua việc cùng học tập, nghiên cứu và tham gia hoạt động với sinh viên Trung Quốc, sinh viên nước ngoài có thể thích nghi nhanh hơn với cuộc sống đại học ở Trung Quốc).","options":["跟中国学生一起学习、做研究和参加活动","只跟本国留学生住在一起练习口语","每天在宿舍里自己看书和上网课","来中国以前先工作两年攒够生活费"],"q":"外国学生通过什么能更快地适应中国的大学生活？"}],"scene":"外国学生在中国大学的学习和生活","sceneVi":"Việc học tập và cuộc sống của sinh viên nước ngoài tại các trường đại học Trung Quốc"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"很多外国学生来中国学习以前，就已经想好了自己的发展方向。","pinyin":"Hěnduō wàiguó xuésheng lái Zhōngguó xuéxí yǐqián, jiù yǐjīng xiǎnghǎo le zìjǐ de fāzhǎn fāngxiàng.","speaker":"Đoạn văn","vi":"Nhiều sinh viên nước ngoài trước khi sang Trung Quốc học tập đã suy nghĩ kỹ về định hướng phát triển của bản thân rồi."},{"hanzi":"有人对经济感兴趣，希望将来在国际公司工作；有人喜欢学医，打算回国后当一名医生；还有人对教育有热情，想要成为一名教师。","pinyin":"Yǒurén duì jīngjì gǎn xìngqù, xīwàng jiānglái zài guójì gōngsī gōngzuò; yǒurén xǐhuan xué yī, dǎsuàn huíguó hòu dāng yì míng yīshēng; hái yǒurén duì jiàoyù yǒu rèqíng, xiǎngyào chéngwéi yì míng jiàoshī.","speaker":"Đoạn văn","vi":"Có người hứng thú với kinh tế, hy vọng tương lai làm việc ở công ty quốc tế; có người thích học y, dự định sau khi về nước sẽ làm bác sĩ; cũng có người nhiệt huyết với giáo dục, muốn trở thành giáo viên."},{"hanzi":"陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。","pinyin":"Chén Tiānzhōng xiǎng xuǎnzé gēn jīngjì yǒuguān de zhuānyè, xīwàng tōngguò xuéxí, liǎojiě gèng duō guójì màoyì fāngmiàn de zhīshi.","speaker":"Đoạn văn","vi":"Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học sẽ hiểu biết thêm nhiều kiến thức về thương mại quốc tế."},{"hanzi":"安妮以后想做一名中文老师，所以要选择国际中文教育专业。","pinyin":"Ānnī yǐhòu xiǎng zuò yì míng Zhōngwén lǎoshī, suǒyǐ yào xuǎnzé guójì Zhōngwén jiàoyù zhuānyè.","speaker":"Đoạn văn","vi":"An Ni sau này muốn làm giáo viên tiếng Trung, vì vậy bạn ấy muốn chọn chuyên ngành Giáo dục tiếng Trung quốc tế."},{"hanzi":"对他们来说，来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":"Duì tāmen láishuō, láidào Zhōngguó liúxué, yì fāngmiàn shì wèile xuéxí yǔyán hé zhīshi, lìng yì fāngmiàn yě shì wèi jiānglái de gōngzuò hé shēnghuó zuò zhǔnbèi.","speaker":"Đoạn văn","vi":"Đối với họ, đến Trung Quốc du học một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống tương lai."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。\" (Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học sẽ hiểu thêm nhiều kiến thức về thương mại quốc tế).","options":["因为他父母希望他以后当一名医生","因为他想做一名国际中文教师","因为他想多了解国际贸易方面的知识","因为这个专业的奖学金金额最高"],"q":"陈天中为什么想选择跟经济有关的专业？"},{"answerIdx":2,"explanation":"Trong bài có câu \"来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。\" (Sang Trung Quốc du học một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống tương lai).","options":["安妮将来想在国际贸易公司工作","很多外国学生来中国后才开始想发展方向","他们来留学既是为了学习，也是为将来做准备","喜欢学医的学生打算毕业后都留在中国当医生"],"q":"关于这段话，下面哪一项是正确的？"}],"scene":"专业选择与职业发展","sceneVi":"Lựa chọn chuyên ngành và phát triển nghề nghiệp"}],"hsk4a-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请进！我给你们介绍一下，这个房子有两个房间，那个大房间出租，房租每月5500元。现在已经收拾好了，想租的话，今天就可以搬进来。","pinyin":"Qǐng jìn! Wǒ gěi nǐmen jièshào yíxià, zhège fángzi yǒu liǎng gè fángjiān, nàge dà fángjiān chūzū, fángzū měi yuè wǔqiān wǔbǎi yuán. Xiànzài yǐjīng shōushi hǎo le, xiǎng zū de huà, jīntiān jiù kěyǐ bān jìnlái.","speaker":"房东","vi":"Mời vào! Để tôi giới thiệu với hai bạn một chút, căn nhà này có hai phòng, phòng lớn kia cho thuê, tiền thuê nhà mỗi tháng 5500 tệ. Hiện tại đã dọn dẹp xong xuôi rồi, nếu muốn thuê thì hôm nay có thể dọn vào ở ngay."},{"hanzi":"嗯，这个房间真不小，还挺亮。小区离我们学校也不远。","pinyin":"Ǹg, zhège fángjiān zhēn bù xiǎo, hái tǐng liàng. Xiǎoqū lí wǒmen xuéxiào yě bù yuǎn.","speaker":"白家月","vi":"Ừm, căn phòng này đúng là không nhỏ, lại khá sáng sủa. Khu chung cư cách trường chúng tôi cũng không xa."},{"hanzi":"是的，我们小区离地铁站也很近，生活上很方便。如果决定租了，告诉我就是了。","pinyin":"Shì de, wǒmen xiǎoqū lí dìtiězhàn yě hěn jìn, shēnghuó shàng hěn fāngbiàn. Rúguǒ juédìng zū le, gàosu wǒ jiùshì le.","speaker":"房东","vi":"Đúng vậy, khu chung cư chúng tôi cũng rất gần ga tàu điện ngầm, sinh hoạt rất thuận tiện. Nếu quyết định thuê rồi thì cứ nói với tôi là được."},{"hanzi":"好的，我们再去看看外边的环境。","pinyin":"Hǎo de, wǒmen zài qù kànkan wàibian de huánjìng.","speaker":"白家月","vi":"Vâng, chúng tôi ra ngoài xem thêm môi trường xung quanh một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài chủ nhà nói \"这个房子有两个房间，那个大房间出租，房租每月5500元。\" (Căn nhà này có hai phòng, cho thuê phòng lớn kia, tiền thuê mỗi tháng 5500 tệ).","options":["两个房间都出租，每月5500元","那个大房间出租，每月5500元","那个小房间出租，每月5000元","整套房子出租，每月6500元"],"q":"房东要出租哪个房间，房租是多少？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"小区离我们学校也不远\" (Khu chung cư cách trường chúng tôi cũng không xa) và chủ nhà nói \"我们小区离地铁站也很近\" (Khu chung cư của chúng tôi cũng rất gần ga tàu điện ngầm).","options":["离学校不远，离地铁站也很近","离学校很近，但附近没有地铁站","离地铁站很近，但离学校非常远","在市中心外面，买东西不太方便"],"q":"关于这个小区的位置，下面哪项符合对话内容？"}],"scene":"白家月想租房，李文陪白家月去看房。","sceneVi":"Bạch Gia Nguyệt muốn thuê nhà, Lý Văn đi cùng Bạch Gia Nguyệt đi xem nhà."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，你看，那边还有个小花园。","pinyin":"Jiāyuè, nǐ kàn, nàbian hái yǒu gè xiǎo huāyuán.","speaker":"李文","vi":"Gia Nguyệt, cậu nhìn kìa, bên kia còn có một vườn hoa nhỏ nữa."},{"hanzi":"嗯，这个小区到处是花，还种了不少树，周围也很安静。","pinyin":"Ǹg, zhège xiǎoqū dàochù shì huā, hái zhòng le bùshǎo shù, zhōuwéi yě hěn ānjìng.","speaker":"白家月","vi":"Ừm, khu chung cư này khắp nơi đều có hoa, còn trồng không ít cây, xung quanh cũng rất yên tĩnh."},{"hanzi":"是啊！这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。","pinyin":"Shì a! Zhège xiǎoqū de huánjìng zhēn búcuò, búguò wǒ tīngshuō, fùjìn yǒu shíjǐ jiā gōngsī, hěnduō gāng bìyè de xuésheng dōu zūzhù zài zhèlǐ. Zhōumò tāmen kěnéng huì wán dào hěn wǎn, kǒngpà huì yǐngxiǎng nǐ xiūxi.","speaker":"李文","vi":"Đúng thế! Môi trường khu này thật sự rất ổn, nhưng mình nghe nói gần đây có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê ở đây. Cuối tuần họ có thể sẽ vui chơi đến rất muộn, e là sẽ ảnh hưởng đến việc nghỉ ngơi của cậu."},{"hanzi":"没关系，我还想多认识一些朋友，和他们一起玩呢。","pinyin":"Méi guānxi, wǒ hái xiǎng duō rènshi yìxiē péngyou, hé tāmen yìqǐ wán ne.","speaker":"白家月","vi":"Không sao đâu, mình còn muốn quen thêm một vài người bạn, cùng chơi với họ nữa cơ."},{"hanzi":"是呢，大家可以一起热闹热闹。","pinyin":"Shì ne, dàjiā kěyǐ yìqǐ rènao rènao.","speaker":"李文","vi":"Đúng đấy, mọi người có thể cùng nhau vui vẻ náo nhiệt."},{"hanzi":"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。","pinyin":"Zhèlǐ fángzū héshì, huánjìng hěn hǎo, érqiě fángdōng yě rèqíng, suǒyǐ wǒ juédìng zū zhège fángzi le, míngtiān jiù rùzhù xīnjiā.","speaker":"白家月","vi":"Tiền thuê ở đây hợp lý, môi trường rất tốt, hơn nữa chủ nhà cũng nhiệt tình, vì vậy mình quyết định thuê căn nhà này rồi, ngày mai sẽ dọn vào nhà mới."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn nói \"附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。\" (Gần đây có hơn chục công ty, nhiều sinh viên mới tốt nghiệp thuê ở đây. Cuối tuần họ có thể chơi rất khuya, e rằng sẽ ảnh hưởng đến việc nghỉ ngơi của bạn).","options":["因为小花园周末总是有人吵架","因为小区旁边有十几家大商场","因为附近住的刚毕业的学生周末可能玩到很晚","因为房东周末经常在家里请朋友吃饭"],"q":"李文为什么担心周末可能会影响白家月休息？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói \"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。\" (Tiền thuê ở đây hợp lý, môi trường rất tốt, hơn nữa chủ nhà cũng nhiệt tình, nên tôi quyết định thuê căn nhà này, ngày mai dọn vào nhà mới luôn).","options":["因为只住两天，今天就搬进去","因为房租便宜、离公司近，下周一搬进去","因为房租合适、环境好、房东热情，明天入住","因为李文也住在这个小区，下个月一起入住"],"q":"白家月为什么决定租这个房子，什么时候搬进去？"}],"scene":"在小区里，白家月和李文继续查看周围环境。","sceneVi":"Trong khu chung cư, Bạch Gia Nguyệt và Lý Văn tiếp tục xem xét môi trường xung quanh."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"8月25日，晴","pinyin":"Bā yuè èrshíwǔ rì, qíng","speaker":"Đoạn văn","vi":"Ngày 25 tháng 8, trời nắng"},{"hanzi":"昨天我顺利租到了合适的房子，今天李文帮我搬家。","pinyin":"Zuótiān wǒ shùnlì zūdào le héshì de fángzi, jīntiān Lǐ Wén bāng wǒ bānjiā.","speaker":"Đoạn văn","vi":"Hôm qua mình đã thuận lợi thuê được căn nhà phù hợp, hôm nay Lý Văn giúp mình chuyển nhà."},{"hanzi":"搬进去的时候，房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin":"Bān jìnqù de shíhou, fángdōng yòu xiàng wǒ jièshào le yíxià fángzi lǐ de dōngxi, bìng gàosu wǒ zhèxiē dōngxi zěnme yòng.","speaker":"Đoạn văn","vi":"Lúc dọn vào, chủ nhà lại giới thiệu cho mình một lượt đồ đạc trong nhà, đồng thời chỉ cho mình cách sử dụng những đồ dùng đó."},{"hanzi":"我看了一下，客厅里有椅子、沙发，还有一台大电视；厨房里有冰箱和一些做饭用的东西，不过，我平常主要在学校食堂吃，基本上不做饭。","pinyin":"Wǒ kàn le yíxià, kètīng lǐ yǒu yǐzi, shāfā, hái yǒu yì tái dà diànshì; chúfáng lǐ yǒu bīngxiāng hé yìxiē zuòfàn yòng de dōngxi, búguò, wǒ píngcháng zhǔyào zài xuéxiào shítáng chī, jīběnshàng bú zuòfàn.","speaker":"Đoạn văn","vi":"Mình xem qua một lượt, trong phòng khách có ghế, ghế sofa, còn có một chiếc tivi lớn; trong bếp có tủ lạnh và một số đồ dùng nấu ăn, tuy nhiên bình thường mình chủ yếu ăn ở nhà ăn trường học, hầu như không nấu cơm."},{"hanzi":"我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。","pinyin":"Wǒ zū de fángjiān lǐ, chúle yì zhāng chuáng yǐwài, hái yǒu yì tái kōngtiáo, yì zhāng shūzhuō hé yì bǎ yǐzi.","speaker":"Đoạn văn","vi":"Trong phòng mình thuê, ngoài một chiếc giường ra, còn có một chiếc điều hòa, một cái bàn học và một chiếc ghế."},{"hanzi":"看完整个房子后，我准备再去买几条毛巾，其他东西还不需要。","pinyin":"Kànwán zhěnggè fángzi hòu, wǒ zhǔnbèi zài qù mǎi jǐ tiáo máojīn, qítā dōngxi hái bù xūyào.","speaker":"Đoạn văn","vi":"Sau khi xem xong toàn bộ căn nhà, mình định đi mua thêm mấy chiếc khăn mặt, những thứ khác thì vẫn chưa cần."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong nhật ký có câu \"我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。\" (Trong căn phòng tôi thuê, ngoài một chiếc giường ra, còn có một máy điều hòa, một bàn học và một cái ghế).","options":["客厅里有床、沙发和冰箱","白家月租的房间里有空调、书桌和电视","厨房里什么做饭用的东西都没有","白家月租的房间里有床、空调、书桌和椅子"],"q":"关于房子里的东西，下面哪一项是对的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我平常主要在学校食堂吃，基本上不做饭\" (Bình thường tôi chủ yếu ăn ở căng tin trường, cơ bản không nấu cơm) và \"我准备再去买几条毛巾，其他东西还不需要\" (Tôi định đi mua thêm mấy chiếc khăn mặt, các đồ khác vẫn chưa cần).","options":["每天自己做饭，打算去买冰箱和椅子","主要在学校食堂吃，打算再去买几条毛巾","主要在外面饭馆吃，打算买一台新电视","经常在李文家吃，什么东西都不需要买"],"q":"白家月平常在哪儿吃饭，搬家后还打算买什么？"}],"scene":"搬进新家后，白家月很开心，写了一篇日记。","sceneVi":"Sau khi dọn vào nhà mới, Bạch Gia Nguyệt rất vui và đã viết một bài nhật ký."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"在李文的帮助下，白家月租到了合适的房子。","pinyin":"Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè zūdào le héshì de fángzi.","speaker":"Đoạn văn","vi":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp."},{"hanzi":"对白家月来说，这次租房并不容易。","pinyin":"Duì Bái Jiāyuè láishuō, zhè cì zūfáng bìng bù róngyì.","speaker":"Đoạn văn","vi":"Đối với Bạch Gia Nguyệt, lần thuê nhà này quả thực không dễ dàng."},{"hanzi":"根据李文的建议，她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。","pinyin":"Gēnjù Lǐ Wén de jiànyì, tā xiān zài zūfáng wǎngzhàn hé App shàng chákàn yǒuguān xìnxī, cházhǎo héshì de fángzi, jiēzhe yòu qù kàn le kàn fángzi, tóngshí liǎojiě fángzi zhōuwéi de huánjìng.","speaker":"Đoạn văn","vi":"Theo lời khuyên của Lý Văn, cô ấy trước tiên xem thông tin liên quan trên các trang web và ứng dụng thuê nhà để tìm căn nhà phù hợp, tiếp theo đến xem nhà trực tiếp, đồng thời tìm hiểu môi trường xung quanh căn nhà."},{"hanzi":"她看了好几个房子，才找到一个位置、环境和价格都合适的，最后顺利租到了理想的房子。","pinyin":"Tā kàn le hǎojǐ gè fángzi, cái zhǎodào yí gè wèizhì, huánjìng hé jiàgé dōu héshì de, zuìhòu shùnlì zūdào le lǐxiǎng de fángzi.","speaker":"Đoạn văn","vi":"Cô ấy đã xem khá nhiều căn nhà mới tìm được một căn có vị trí, môi trường và giá cả đều phù hợp, cuối cùng đã thuận lợi thuê được căn nhà lý tưởng."},{"hanzi":"租房的时候，李文告诉白家月，在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","pinyin":"Zūfáng de shíhou, Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, yóuyú hěnduō gāng gōngzuò de niánqīngrén gōngzī hái bú tài gāo, suǒyǐ tāmen yì kāishǐ yě bù mǎifáng, dōu xuǎnzé zūfáng.","speaker":"Đoạn văn","vi":"Khi thuê nhà, Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, do lương của nhiều bạn trẻ mới đi làm chưa cao lắm nên ban đầu họ đều không mua nhà mà chọn thuê nhà."},{"hanzi":"工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。","pinyin":"Gōngzuò jǐ nián hòu, bùshǎo rén jiù huì mǎifáng, yīnwèi dàjiā yìzhí juéde, yǒu fáng cái yǒu jiā, yǒu zìjǐ de fángzi huì gèng yǒu ānquángǎn.","speaker":"Đoạn văn","vi":"Sau vài năm đi làm, không ít người sẽ mua nhà, bởi vì mọi người luôn cảm thấy có nhà mới có gia đình, có căn nhà của riêng mình sẽ có cảm giác an toàn hơn."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。\" (Cô ấy trước tiên xem thông tin liên quan trên trang web và ứng dụng thuê nhà, tìm căn phù hợp, tiếp đó lại đi xem nhà, đồng thời tìm hiểu môi trường xung quanh).","options":["先在租房网站和软件上查信息，再去实地看房和了解周围环境","只看了一套房子就立刻决定租下来了","请房东先发照片，没有去现场看周围环境","完全让李文帮她选好房子并签了合同"],"q":"白家月这次是怎么找到理想房子的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。\" (Sau khi đi làm vài năm, không ít người sẽ mua nhà, vì mọi người luôn cảm thấy có nhà mới có gia đình, có nhà của riêng mình sẽ có cảm giác an toàn hơn).","options":["因为租房比买房的价格贵得多","因为学校要求毕业后必须买房","因为他们觉得有房才有家，更有安全感","因为刚工作时工资很高，已经存够了钱"],"q":"在中国，为什么不少人工作几年后会选择买房？"}],"scene":"怎样租到合适的房子","sceneVi":"Làm thế nào để thuê được căn nhà phù hợp"}],"hsk4a-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，花园小区怎么走？","pinyin":"Qǐngwèn, Huāyuán Xiǎoqū zěnme zǒu?","speaker":"陈天中","vi":"Xin hỏi, Khu dân cư Hoa Viên đi thế nào ạ?"},{"hanzi":"你往前走，到十字路口不要过马路，直接右转就到小区门口了。正好我也去那边，一起走吧。","pinyin":"Nǐ wǎng qián zǒu, dào shízì lùkǒu búyào guò mǎlù, zhíjiē yòu zhuǎn jiù dào xiǎoqū ménkǒu le. Zhènghǎo wǒ yě qù nàbiān, yìqǐ zǒu ba.","speaker":"同学","vi":"Bạn đi thẳng về phía trước, đến ngã tư đừng qua đường, rẽ phải luôn là tới cổng khu dân cư rồi. Vừa hay mình cũng đi hướng đó, đi cùng nhé."},{"hanzi":"好的。我刚来中国，不熟悉路。北京真是太大了。","pinyin":"Hǎo de. Wǒ gāng lái Zhōngguó, bù shúxi lù. Běijīng zhēnshi tài dà le.","speaker":"陈天中","vi":"Được ạ. Mình mới đến Trung Quốc, chưa quen đường. Bắc Kinh thật sự rộng quá."},{"hanzi":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。你也可以用手机地图，很容易就能找到目的地。","pinyin":"Běijīng dà shì dà, búguò zhèbiān de lù jīběnshang dōu shì zhèngnán zhèngběi, zhèngdōng zhèngxī de, hěn hǎo zhǎo. Nǐ yě kěyǐ yòng shǒujī dìtú, hěn róngyì jiù néng zhǎodào mùdìdì.","speaker":"同学","vi":"Bắc Kinh rộng thì rộng thật, nhưng đường ở đây về cơ bản đều theo hướng chính nam chính bắc, chính đông chính tây, rất dễ tìm. Bạn cũng có thể dùng bản đồ trên điện thoại, rất dễ dàng tìm được điểm đến."},{"hanzi":"嗯，不过很多中文地名我还不认识。","pinyin":"Ǹg, búguò hěnduō Zhōngwén dìmíng wǒ hái bú rènshi.","speaker":"陈天中","vi":"Ừ, nhưng mà nhiều tên địa danh tiếng Trung mình vẫn chưa biết mặt chữ."},{"hanzi":"没关系，你很快就会熟悉的。","pinyin":"Méi guānxi, nǐ hěn kuài jiù huì shúxi de.","speaker":"同学","vi":"Không sao đâu, bạn sẽ nhanh chóng quen thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài bạn học chỉ đường \"你往前走，到十字路口不要过马路，直接右转就到小区门口了。\" (Bạn đi thẳng về phía trước, đến ngã tư đừng qua đường, rẽ phải ngay là tới cổng khu dân cư rồi).","options":["往前走，过了十字路口再左转","往前走，到十字路口不过马路直接右转","先往后走，看到小花园再过马路","坐地铁到下一站，出站后左转"],"q":"按照同学的指路，陈天中怎么走到花园小区？"},{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung nói \"嗯，不过很多中文地名我还不认识。\" (Ừ, nhưng nhiều tên địa danh tiếng Trung mình vẫn chưa biết mặt chữ).","options":["因为他的手机停机了，没有信号","因为北京的路都不是正南正北的","因为很多中文地名他还不认识","因为他的手机里还没有下载地图软件"],"q":"陈天中为什么觉得用手机地图还是不太容易？"}],"scene":"一天，陈天中从学校出来迷路了，就向一位同学问路。","sceneVi":"Một ngày nọ, Trần Thiên Trung từ trường đi ra bị lạc đường nên đã hỏi đường một bạn học."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"前两天和李文喝咖啡时，他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。","pinyin":"Qián liǎng tiān hé Lǐ Wén hē kāfēi shí, tā bāng wǒ xiàzài le Wēixìn hé Zhīfùbǎo, jiāo wǒ rènshi lǐbiān de Hànzì, hái jiāo wǒ yòng shǒujī jìnxíng zhīfù.","speaker":"陈天中","vi":"Mấy hôm trước lúc uống cà phê với Lý Văn, cậu ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận biết chữ Hán bên trong, còn dạy mình thanh toán bằng điện thoại nữa."},{"hanzi":"他也教了我怎么用这两个软件。","pinyin":"Tā yě jiāo le wǒ zěnme yòng zhè liǎng gè ruǎnjiàn.","speaker":"白家月","vi":"Cậu ấy cũng dạy mình cách dùng hai phần mềm này đấy."},{"hanzi":"现在我不仅会扫码结账，还会用手机在网上购物了。昨天我就在网上订了一台电脑，今天下午一点送到。","pinyin":"Xiànzài wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì yòng shǒujī zài wǎngshàng gòuwù le. Zuótiān wǒ jiù zài wǎngshàng dìng le yì tái diànnǎo, jīntiān xiàwǔ yì diǎn sòngdào.","speaker":"陈天中","vi":"Bây giờ mình không những biết quét mã thanh toán mà còn biết dùng điện thoại mua sắm trực tuyến rồi. Hôm qua mình vừa đặt mua một chiếc máy tính trên mạng, chiều nay một giờ sẽ giao tới."},{"hanzi":"学会了这些，我们在中国生活真是方便了不少。","pinyin":"Xuéhuì le zhèxiē, wǒmen zài Zhōngguó shēnghuó zhēnshi fāngbiàn le bùshǎo.","speaker":"白家月","vi":"Học được những thứ này, cuộc sống của chúng ta ở Trung Quốc thật sự tiện lợi hơn rất nhiều."},{"hanzi":"对。快递员要到了，我得马上回去！家月，明天见！","pinyin":"Duì. Kuàidìyuán yào dào le, wǒ děi mǎshàng huíqu! Jiāyuè, míngtiān jiàn!","speaker":"陈天中","vi":"Đúng vậy. Nhân viên giao hàng sắp tới rồi, mình phải về ngay đây! Gia Nguyệt, mai gặp nhé!"},{"hanzi":"好的，天中，再见。","pinyin":"Hǎo de, Tiānzhōng, zàijiàn.","speaker":"白家月","vi":"Được, Thiên Trung, tạm biệt."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。\" (Anh ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận mặt chữ Hán bên trong, còn dạy mình thanh toán bằng điện thoại).","options":["教他怎么在学校食堂点菜和付款","帮他下载微信和支付宝，教他认字和手机支付","帮他在网上修好了一台旧电脑","教他怎么在网站上找房子和签合同"],"q":"前两天和李文喝咖啡时，李文教了陈天中什么？"},{"answerIdx":3,"explanation":"Trong bài Trần Thiên Trung nói \"昨天我就在网上订了一台电脑，今天下午一点送到\" và \"快递员要到了，我得马上回去！\" (Hôm qua mình đặt mua một chiếc máy tính trên mạng, 1 giờ chiều nay giao tới... Nhân viên giao hàng sắp đến rồi, mình phải về ngay!).","options":["因为下午一点他还有一节中文课","因为他约了李文再去喝咖啡","因为他忘了带手机和现金结账","因为他昨天订的电脑快递员要送到了"],"q":"陈天中为什么着急跟白家月说再见、马上回去？"}],"scene":"中午下课后，白家月和陈天中在学校食堂相遇，两人边吃饭边聊天儿。","sceneVi":"Buổi trưa sau khi tan học, Bạch Gia Nguyệt và Trần Thiên Trung gặp nhau ở nhà ăn trường học, hai người vừa ăn cơm vừa trò chuyện."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"白家月和陈天中刚到北京时就发现，中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。","pinyin":"Bái Jiāyuè hé Chén Tiānzhōng gāng dào Běijīng shí jiù fāxiàn, Zhōngguórén zài fànguǎn huò chāoshì jiézhàng shí, jīhū dōu yòng shǒujī zhīfù, zhǐyǒu tāmen yòng xiànjīn jiézhàng.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt và Trần Thiên Trung khi mới đến Bắc Kinh liền phát hiện người Trung Quốc khi thanh toán ở nhà hàng hay siêu thị hầu như đều trả bằng điện thoại, chỉ có họ dùng tiền mặt."},{"hanzi":"在李文的帮助下，白家月和陈天中也都学会了用手机支付、网购、寄快递等等。","pinyin":"Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè hé Chén Tiānzhōng yě dōu xuéhuì le yòng shǒujī zhīfù, wǎnggòu, jì kuàidì děngděng.","speaker":"Đoạn văn","vi":"Dưới sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cũng đều học được cách thanh toán bằng điện thoại, mua sắm trực tuyến, gửi chuyển phát nhanh, v.v."},{"hanzi":"在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","pinyin":"Zài Zhōngguó wǎnggòu, bùjǐn xuǎnzé duō, jiàgé bù gāo, érqiě sònghuò hěn kuài, hěnduō liúxuéshēng shènzhì gǎibiàn le zìjǐ de gòuwù xíguàn.","speaker":"Đoạn văn","vi":"Mua sắm trực tuyến ở Trung Quốc không chỉ nhiều lựa chọn, giá cả phải chăng mà giao hàng còn rất nhanh, nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"hanzi":"不过，由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。","pinyin":"Búguò, yóuyú wǎnggòu tài fāngbiàn le, dòngdong shǒuzhǐ jiù néng mǎidào xiǎng yào de dōngxi, tāmen yě kāishǐ dānxīn zìjǐ zài wǎnggòu shí huì luàn huā qián.","speaker":"Đoạn văn","vi":"Tuy nhiên, vì mua sắm trực tuyến quá tiện lợi, chỉ cần cử động ngón tay là có thể mua được món đồ mình muốn, nên họ cũng bắt đầu lo lắng bản thân sẽ tiêu tiền bừa bãi khi mua hàng online."},{"hanzi":"怎么才能管住自己不乱花钱呢？","pinyin":"Zěnme cái néng guǎnzhù zìjǐ bú luàn huā qián ne?","speaker":"Đoạn văn","vi":"Làm thế nào để kiềm chế bản thân không tiêu tiền bừa bãi đây?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。\" (Người Trung Quốc khi thanh toán ở nhà hàng hoặc siêu thị hầu như đều dùng điện thoại trả tiền, chỉ có hai bạn ấy dùng tiền mặt).","options":["饭馆和超市都不收手机支付，只收现金","中国人几乎都用手机支付，只有他们用现金","所有留学生都已经习惯用手机寄快递了","中国人在超市买东西时不用排队结账"],"q":"刚到北京时，白家月和陈天中在结账时发现了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。\" (Do mua sắm trực tuyến quá tiện lợi, chỉ cần nhúc nhích ngón tay là mua được thứ mình muốn, nên họ cũng bắt đầu lo lắng mình sẽ tiêu tiền bừa bãi khi mua sắm online).","options":["因为网购的东西价格都比商店贵很多","因为网购时快递费非常高","因为网购太方便，动动手指就能买到想要的东西","因为父母每个月给他们的钱太多了"],"q":"为什么他们开始担心自己在网购时会乱花钱？"}],"scene":"生活新体验","sceneVi":"Trải nghiệm cuộc sống mới"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"网上购物或者订票时，我们经常需要提供姓名、手机号、身份证号等个人信息。","pinyin":"Wǎngshàng gòuwù huòzhě dìng piào shí, wǒmen jīngcháng xūyào tígōng xìngmíng, shǒujī hào, shēnfènzhèng hào děng gèrén xìnxī.","speaker":"Đoạn văn","vi":"Khi mua sắm trực tuyến hoặc đặt vé, chúng ta thường xuyên cần cung cấp thông tin cá nhân như họ tên, số điện thoại, số căn cước công dân."},{"hanzi":"在提供这些信息时，我们也会担心：我的个人信息能否得到保护？","pinyin":"Zài tígōng zhèxiē xìnxī shí, wǒmen yě huì dānxīn: wǒ de gèrén xìnxī néngfǒu dédào bǎohù?","speaker":"Đoạn văn","vi":"Khi cung cấp những thông tin này, chúng ta cũng sẽ lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không?"},{"hanzi":"于是，有人在网上说出了自己的担心，很快就有人给出了一些建议。","pinyin":"Yúshì, yǒurén zài wǎngshàng shuōchū le zìjǐ de dānxīn, hěn kuài jiù yǒurén gěichū le yìxiē jiànyì.","speaker":"Đoạn văn","vi":"Thế là có người đã nói lên nỗi lo của mình trên mạng, rất nhanh sau đó đã có người đưa ra một số lời khuyên."},{"hanzi":"比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……","pinyin":"Bǐrú, bié bǎ mìmǎ suíbiàn gàosu biérén, bú zài wǎngshàng fā zìjǐ de chēpiào, jīpiào xìnxī……","speaker":"Đoạn văn","vi":"Ví dụ như đừng tùy tiện nói mật khẩu cho người khác, không đăng thông tin vé tàu, vé máy bay của mình lên mạng..."},{"hanzi":"现在，很多国家也通过技术、法律等手段来保证个人信息安全。","pinyin":"Xiànzài, hěnduō guójiā yě tōngguò jìshù, fǎlǜ děng shǒuduàn lái bǎozhèng gèrén xìnxī ānquán.","speaker":"Đoạn văn","vi":"Hiện nay, nhiều quốc gia cũng thông qua các biện pháp như công nghệ, pháp luật để bảo đảm an toàn thông tin cá nhân."},{"hanzi":"比如中国的网络安全法、个人信息保护法等就很好地保护了人们的个人信息。","pinyin":"Bǐrú Zhōngguó de Wǎngluò Ānquán Fǎ, Gèrén Xìnxī Bǎohù Fǎ děng jiù hěn hǎo de bǎohù le rénmen de gèrén xìnxī.","speaker":"Đoạn văn","vi":"Ví dụ như Luật An ninh mạng, Luật Bảo vệ thông tin cá nhân của Trung Quốc đã bảo vệ rất tốt thông tin cá nhân của người dân."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……\" (Ví dụ như đừng tùy tiện nói mật khẩu cho người khác, không đăng thông tin vé tàu, vé máy bay của mình lên mạng...).","options":["网上买东西时不要写自己的姓名","不要把密码随便告诉别人，不在网上发车票信息","买完机票后要把照片发到网上留作纪念","千万不要用手机在网上订票或购物"],"q":"为了保护个人信息，下面哪项是文中提到的建议？"},{"answerIdx":0,"explanation":"Trong bài có câu \"现在，很多国家也通过技术、法律等手段来保证个人信息安全。\" (Hiện nay, nhiều quốc gia cũng thông qua các biện pháp như kỹ thuật, pháp luật... để bảo đảm an toàn thông tin cá nhân).","options":["技术、法律等手段","只允许用现金购物","禁止大家在网上订车票","让每个人都更换新手机号"],"q":"现在很多国家主要通过什么手段来保证个人信息安全？"}],"scene":"用手机时如何保护个人信息","sceneVi":"Làm thế nào để bảo vệ thông tin cá nhân khi sử dụng điện thoại"}],"hsk4a-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"啊，我的手机停机了！怎么办啊？","pinyin":"Ā, wǒ de shǒujī tíngjī le! Zěnme bàn a?","speaker":"陈天中","vi":"Á, điện thoại của mình bị khóa mạng rồi! Làm sao bây giờ?"},{"hanzi":"你好，你看上去很着急，需要帮忙吗？","pinyin":"Nǐ hǎo, nǐ kànshàngqu hěn zháojí, xūyào bāngmáng ma?","speaker":"路人","vi":"Chào bạn, trông bạn rất vội, có cần giúp gì không?"},{"hanzi":"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。","pinyin":"Wǒ wàng le jiāo diànhuàfèi, shǒujī tíngjī le. Wǒ méi dài xiànjīn, shǒujī méiyǒu xìnhào, shàngbuliǎo wǎng, mǎibuliǎo dìtiěpiào le.","speaker":"陈天中","vi":"Mình quên đóng tiền điện thoại nên bị khóa máy rồi. Mình lại không mang tiền mặt, điện thoại không có sóng, không lên mạng được, không mua được vé tàu điện ngầm nữa rồi."},{"hanzi":"你要去哪儿？我帮你买张票。","pinyin":"Nǐ yào qù nǎr? Wǒ bāng nǐ mǎi zhāng piào.","speaker":"路人","vi":"Bạn muốn đi đâu? Mình mua giúp bạn một tấm vé."},{"hanzi":"太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。","pinyin":"Tài gǎnxiè nǐ le, wǒ yào qù Běijīng Dàxué Zhàn. Duìle, néng bu néng gàosu wǒ nǐ de liánxì fāngshì? Wǒ xiǎng bǎ qián huángěi nǐ.","speaker":"陈天中","vi":"Cảm ơn bạn nhiều lắm, mình muốn đến ga Đại học Bắc Kinh. À đúng rồi, bạn có thể cho mình biết thông tin liên hệ được không? Mình muốn trả lại tiền cho bạn."},{"hanzi":"别客气，很高兴能帮到你。","pinyin":"Bié kèqi, hěn gāoxìng néng bāngdào nǐ.","speaker":"路人","vi":"Đừng khách sáo, rất vui vì đã giúp được bạn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。\" (Mình quên nộp tiền điện thoại nên máy bị khóa chiều. Mình không mang tiền mặt, điện thoại không có sóng, không lên mạng được, không mua được vé tàu điện ngầm nữa).","options":["因为地铁站的自动售票机坏了","因为他忘了交电话费导致手机停机，又没带现金","因为他不知道北京大学站在哪一条线上","因为他的钱包和手机在路上弄丢了"],"q":"陈天中为什么买不了地铁票？"},{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"对了，能不能告诉我你的联系方式？我想把钱还给你。\" (À đúng rồi, bạn có thể cho mình biết thông tin liên hệ của bạn không? Mình muốn trả lại tiền cho bạn).","options":["因为他想请路人教他用中文买票","因为他想以后把买票的钱还给路人","因为他想邀请路人一起去北京大学玩","因为他想借路人的手机给李文打电话"],"q":"陈天中为什么想问路人的联系方式？"}],"scene":"在地铁站，陈天中准备买票进站。","sceneVi":"Ở ga tàu điện ngầm, Trần Thiên Trung chuẩn bị mua vé vào ga."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"阿姨，您怎么站在这儿不上楼？","pinyin":"Āyí, nín zěnme zhàn zài zhèr bú shànglóu?","speaker":"白家月","vi":"Cô ơi, sao cô đứng ở đây mà chưa lên lầu ạ?"},{"hanzi":"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。","pinyin":"Wǒ kāichē qù chāoshì mǎi le bùshǎo dōngxi, gāng ná guòlái le yìxiē. Wǒ xiān xiūxi yíhuìr, zài qù chē lǐ ná shèngxià de.","speaker":"邻居","vi":"Cô lái xe đi siêu thị mua khá nhiều đồ, vừa mới mang qua một ít. Cô nghỉ một lát rồi ra xe lấy nốt số còn lại."},{"hanzi":"我正好要上楼，我帮您提上去吧。","pinyin":"Wǒ zhènghǎo yào shànglóu, wǒ bāng nín tí shàngqù ba.","speaker":"白家月","vi":"Cháu vừa hay cũng định lên lầu, để cháu xách lên giúp cô nhé."},{"hanzi":"不用不用，这几个袋子太重了，我自己拿吧。","pinyin":"Búyòng búyòng, zhè jǐ gè dàizi tài zhòng le, wǒ zìjǐ ná ba.","speaker":"邻居","vi":"Không cần đâu, mấy túi này nặng lắm, để cô tự mang."},{"hanzi":"没事，我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":"Méishì, wǒ tízhe zhèxiē dōngxi jiù suàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù a.","speaker":"白家月","vi":"Không sao đâu ạ, cháu xách mấy đồ này coi như rèn luyện sức khỏe luôn, vả lại hàng xóm với nhau vốn dĩ phải giúp đỡ lẫn nhau mà."},{"hanzi":"谢谢家月！那就辛苦你了。","pinyin":"Xièxie Jiāyuè! Nà jiù xīnkǔ nǐ le.","speaker":"邻居","vi":"Cảm ơn Gia Nguyệt nhé! Vậy làm phiền cháu rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài cô hàng xóm nói \"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。\" (Cô lái xe đi siêu thị mua khá nhiều đồ, vừa mới mang qua một ít. Cô nghỉ một lát trước rồi mới ra xe lấy số còn lại).","options":["因为她忘了带家里的钥匙","因为她在楼下等白家月一起回去","因为她买了不少东西，刚拿来一部分，想歇会儿再去车里拿剩下的","因为电梯坏了，她一个人提不动袋子"],"q":"邻居阿姨为什么站在楼下没有马上上楼？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。\" (Cháu xách mấy đồ này coi như tập thể dục luôn, vả lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ ạ).","options":["她说她今天正好想锻炼身体，而且邻居之间应该互相帮助","她说自己家里也有一辆车可以帮忙搬","她说袋子其实一点儿也不重，自己力气很大","她说如果阿姨不让帮忙，她就不上楼了"],"q":"白家月说了什么让阿姨同意她帮忙提东西？"}],"scene":"在楼下，白家月遇到了住在同一层的邻居。","sceneVi":"Ở dưới lầu, Bạch Gia Nguyệt gặp người hàng xóm sống cùng tầng."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"在城市里，人们出行的方式越来越多。","pinyin":"Zài chéngshì lǐ, rénmen chūxíng de fāngshì yuèláiyuè duō.","speaker":"Đoạn văn","vi":"Ở trong thành phố, phương thức đi lại của mọi người ngày càng đa dạng."},{"hanzi":"短距离出行时，骑自行车往往是人们常见的选择。","pinyin":"Duǎn jùlí chūxíng shí, qí zìxíngchē wǎngwǎng shì rénmen chángjiàn de xuǎnzé.","speaker":"Đoạn văn","vi":"Khi di chuyển quãng đường ngắn, đạp xe đạp thường là lựa chọn phổ biến của mọi người."},{"hanzi":"白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。","pinyin":"Bái Jiāyuè jiù hěn xǐhuan qíchē qù xuéxiào, tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt rất thích đạp xe đi học, cô ấy thấy cách này vừa tiện lợi, vừa rèn luyện sức khỏe, lại còn bảo vệ môi trường."},{"hanzi":"除了骑自行车，人们还会选择骑电动车。","pinyin":"Chúle qí zìxíngchē, rénmen hái huì xuǎnzé qí diàndòngchē.","speaker":"Đoạn văn","vi":"Ngoài đạp xe đạp, mọi người còn chọn đi xe máy điện."},{"hanzi":"电动车速度快，价格不高，充电也很方便，所以越来越流行。","pinyin":"Diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn, suǒyǐ yuèláiyuè liúxíng.","speaker":"Đoạn văn","vi":"Xe máy điện tốc độ nhanh, giá cả không cao, sạc điện cũng rất tiện, vì vậy ngày càng phổ biến."},{"hanzi":"陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。","pinyin":"Chén Tiānzhōng píngshí yě qí zìxíngchē, búguò wèile shěng lìqi, tā zuìjìn dǎsuàn mǎi yí liàng diàndòngchē.","speaker":"Đoạn văn","vi":"Trần Thiên Trung bình thường cũng đạp xe đạp, nhưng để đỡ tốn sức, gần đây cậu ấy dự định mua một chiếc xe máy điện."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。\" (Bạch Gia Nguyệt rất thích đạp xe đi học, bạn ấy thấy như vậy vừa tiện lợi, vừa rèn luyện sức khỏe, lại vừa bảo vệ môi trường).","options":["因为骑自行车速度最快，而且不用花钱","因为既方便，又能锻炼身体，还能保护环境","因为学校门口没有公交车站和地铁站","因为骑自行车比骑电动车更省力气"],"q":"白家月为什么喜欢骑自行车去学校？"},{"answerIdx":2,"explanation":"Trong bài có câu \"陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。\" (Trần Thiên Trung bình thường cũng đạp xe, nhưng để đỡ tốn sức, gần đây cậu ấy dự định mua một chiếc xe điện).","options":["因为他的自行车刚刚坏了","因为骑电动车能帮他锻炼身体","因为骑电动车可以省力气","因为学校规定留学生不能骑自行车"],"q":"陈天中最近为什么打算买一辆电动车？"}],"scene":"短距离出行的新选择","sceneVi":"Lựa chọn mới cho việc di chuyển quãng đường ngắn"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"在中国，乘客可以在不少地铁站里直接扫码购买食物和饮料，有的地铁站还提供免费借雨伞、发雨衣等服务。","pinyin":"Zài Zhōngguó, chéngkè kěyǐ zài bùshǎo dìtiězhàn lǐ zhíjiē sǎomǎ gòumǎi shíwù hé yǐnliào, yǒude dìtiězhàn hái tígōng miǎnfèi jiè yǔsǎn, fā yǔyī děng fúwù.","speaker":"Đoạn văn","vi":"Ở Trung Quốc, hành khách có thể trực tiếp quét mã mua đồ ăn và thức uống ngay tại nhiều ga tàu điện ngầm, một số ga còn cung cấp dịch vụ mượn ô miễn phí, phát áo mưa, v.v."},{"hanzi":"有些地铁站附近公司比较多，工作日站里还有早餐车，没来得及吃早饭的人在这里就能买到热包子和牛奶等，省了不少时间。","pinyin":"Yǒuxiē dìtiězhàn fùjìn gōngsī bǐjiào duō, gōngzuòrì zhàn lǐ hái yǒu zǎocānchē, méi láidejí chī zǎofàn de rén zài zhèlǐ jiù néng mǎidào rè bāozi hé niúnǎi děng, shěng le bùshǎo shíjiān.","speaker":"Đoạn văn","vi":"Một số ga tàu điện ngầm có khá nhiều công ty ở gần, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng, những người chưa kịp ăn sáng có thể mua bánh bao nóng và sữa ở đây, tiết kiệm được rất nhiều thời gian."},{"hanzi":"有的地铁站里甚至还有鲜花店，乘客下班时可以顺便买花送给家人。","pinyin":"Yǒude dìtiězhàn lǐ shènzhì hái yǒu xiānhuādiàn, chéngkè xiàbān shí kěyǐ shùnbiàn mǎi huā sònggěi jiārén.","speaker":"Đoạn văn","vi":"Có ga tàu điện ngầm thậm chí còn có cả tiệm hoa tươi, hành khách khi tan làm có thể tiện đường mua hoa tặng cho người thân."},{"hanzi":"这些小小的服务，不仅方便了人们的出行，也让大家的心情变得更加愉快。","pinyin":"Zhèxiē xiǎoxiǎo de fúwù, bùjǐn fāngbiàn le rénmen de chūxíng, yě ràng dàjiā de xīnqíng biàndé gèngjiā yúkuài.","speaker":"Đoạn văn","vi":"Những dịch vụ nho nhỏ này không chỉ giúp việc đi lại của mọi người thêm thuận tiện mà còn khiến tâm trạng của mọi người trở nên vui vẻ hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有些地铁站附近公司比较多，工作日站里还有早餐车\" (Một số ga tàu điện ngầm có khá nhiều công ty ở gần đó, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng).","options":["离大学校园很近的地铁站","附近公司比较多的地铁站","站里有鲜花店的地铁站","只有周末才开放的地铁站"],"q":"什么样的地铁站在工作日通常会有早餐车？"},{"answerIdx":3,"explanation":"Trong bài có nhắc đến quét mã mua đồ ăn thức uống (\"扫码购买食物和饮料\"), mượn ô/phát áo mưa miễn phí (\"免费借雨伞、发雨衣\") và tiệm hoa tươi (\"鲜花店\"), hoàn toàn không nhắc đến dịch vụ sửa xe đạp miễn phí.","options":["扫码购买食物和饮料","免费借雨伞或者发雨衣","下班时在鲜花店买花送家人","免费帮乘客修理自行车"],"q":"关于中国地铁站里的服务，下面哪一项文中没有提到？"}],"scene":"地铁站里的贴心服务","sceneVi":"Dịch vụ chu đáo trong ga tàu điện ngầm"}],"hsk4a-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":"Jiāyuè, nǐ lái Zhōngguó zhìshǎo liǎng gè yuè le, xíguàn chī Zhōngcān le ma?","speaker":"刘明","vi":"Gia Nguyệt, cậu đến Trung Quốc ít nhất hai tháng rồi, đã quen ăn món Trung chưa?"},{"hanzi":"习惯了，而且我很喜欢吃中国菜。","pinyin":"Xíguàn le, érqiě wǒ hěn xǐhuan chī Zhōngguó cài.","speaker":"白家月","vi":"Quen rồi, hơn nữa mình rất thích ăn món Trung Quốc."},{"hanzi":"你还没吃过水煮鱼吧？这是我专门为你做的。","pinyin":"Nǐ hái méi chīguo shuǐzhǔyú ba? Zhè shì wǒ zhuānmén wèi nǐ zuò de.","speaker":"王一雪","vi":"Cậu vẫn chưa ăn cá luộc cay Tứ Xuyên bao giờ đúng không? Món này mình làm riêng cho cậu đấy."},{"hanzi":"看起来不像水煮鱼，更像“油煮鱼”。","pinyin":"Kàn qǐlái bú xiàng shuǐzhǔyú, gèng xiàng “yóuzhǔyú”.","speaker":"白家月","vi":"Nhìn không giống 'cá luộc nước', mà giống 'cá luộc dầu' hơn."},{"hanzi":"这道菜是先用水把鱼煮熟，最后再倒上辣椒油，其实只有最上面那一层是油。你尝尝，对你来说辣不辣？","pinyin":"Zhè dào cài shì xiān yòng shuǐ bǎ yú zhǔshú, zuìhòu zài dàoshàng làjiāoyóu, qíshí zhǐyǒu zuì shàngmiàn nà yì céng shì yóu. Nǐ chángchang, duì nǐ láishuō là bu là?","speaker":"王一雪","vi":"Món này là luộc chín cá bằng nước trước, cuối cùng mới rưới dầu ớt lên, thực ra chỉ có lớp trên cùng là dầu thôi. Cậu nếm thử xem, đối với cậu có cay không?"},{"hanzi":"辣是辣，但是非常好吃！","pinyin":"Là shì là, dànshì fēicháng hǎochī!","speaker":"白家月","vi":"Cay thì có cay, nhưng mà rất ngon!"},{"hanzi":"那你多吃点儿，不要客气。","pinyin":"Nà nǐ duō chī diǎnr, búyào kèqi.","speaker":"王一雪","vi":"Vậy cậu ăn nhiều một chút, đừng khách sáo."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"家月，你来中国至少两个月了\" (Gia Nguyệt, bạn đến Trung Quốc ít nhất hai tháng rồi), nên đáp án đúng là ít nhất hai tháng.","options":["最多一个月","至少两个月","不到两个星期","差不多一年了"],"q":"白家月来中国多长时间了？"},{"answerIdx":0,"explanation":"Trong bài, Bạch Gia Nguyệt nhận xét về món cá luộc cay: \"辣是辣，但是非常好吃！\" (Cay thì có cay, nhưng rất ngon!), nên đáp án đúng là tuy cay nhưng rất ngon.","options":["虽然辣，但是非常好吃","一点儿也不辣，味道很一般","油太多了，所以她不想吃","鱼还没煮熟，吃起来不太好"],"q":"白家月觉得水煮鱼怎么样？"}],"scene":"在刘明和王一雪家，夫妻两人请白家月和李文吃饭。","sceneVi":"Tại nhà Lưu Minh và Vương Nhất Tuyết, hai vợ chồng mời Bạch Gia Nguyệt và Lý Văn ăn cơm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我听李文说，你现在也爱吃辣了？","pinyin":"Wǒ tīng Lǐ Wén shuō, nǐ xiànzài yě ài chī là le?","speaker":"王一雪","vi":"Mình nghe Lý Văn nói, bây giờ cậu cũng thích ăn cay rồi à?"},{"hanzi":"是的，来中国以后，我越来越喜欢吃辣了。","pinyin":"Shì de, lái Zhōngguó yǐhòu, wǒ yuèláiyuè xǐhuan chī là le.","speaker":"白家月","vi":"Đúng vậy, sau khi đến Trung Quốc, mình càng ngày càng thích ăn cay."},{"hanzi":"我们以前不太敢吃辣，吃完可能会肚子不舒服，不过现在也慢慢适应了。","pinyin":"Wǒmen yǐqián bú tài gǎn chī là, chīwán kěnéng huì dùzi bù shūfu, búguò xiànzài yě mànmàn shìyìng le.","speaker":"王一雪","vi":"Trước đây bọn mình không dám ăn cay lắm, ăn xong có thể sẽ bị khó chịu ở bụng, nhưng bây giờ cũng dần dần quen rồi."},{"hanzi":"对，我们现在都不怕辣了。家月，你是“不怕辣”还是“怕不辣”？","pinyin":"Duì, wǒmen xiànzài dōu bú pà là le. Jiāyuè, nǐ shì “bú pà là” háishi “pà bú là”?","speaker":"刘明","vi":"Đúng thế, bây giờ bọn mình đều không sợ cay nữa rồi. Gia Nguyệt, cậu thuộc kiểu 'không sợ cay' hay 'sợ không cay'?"},{"hanzi":"中文真有意思，相同的字，顺序一换，意思就变了。","pinyin":"Zhōngwén zhēn yǒuyìsi, xiāngtóng de zì, shùnxù yí huàn, yìsi jiù biàn le.","speaker":"白家月","vi":"Tiếng Trung thật thú vị, những chữ giống nhau, chỉ cần đổi thứ tự một chút là ý nghĩa đã thay đổi rồi."},{"hanzi":"你的中文水平够高的，这都听懂了！你说得对，“不怕辣”是说不怕吃辣的菜，“怕不辣”是担心菜还不够辣呢。","pinyin":"Nǐ de Zhōngwén shuǐpíng gòu gāo de, zhè dōu tīngdǒng le! Nǐ shuō de duì, “bú pà là” shì shuō bú pà chī là de cài, “pà bú là” shì dānxīn cài hái búgòu là ne.","speaker":"李文","vi":"Trình độ tiếng Trung của cậu cao thật đấy, câu này cũng nghe hiểu được! Cậu nói đúng rồi, 'không sợ cay' là nói không sợ ăn món cay, còn 'sợ không cay' là lo món ăn vẫn chưa đủ cay đấy."},{"hanzi":"我还达不到“怕不辣”的水平，甚至也不能算“不怕辣”，只是喜欢吃辣。","pinyin":"Wǒ hái dábudào “pà bú là” de shuǐpíng, shènzhì yě bù néng suàn “bú pà là”, zhǐshì xǐhuan chī là.","speaker":"白家月","vi":"Mình vẫn chưa đạt đến trình độ 'sợ không cay', thậm chí cũng chưa thể tính là 'không sợ cay', chỉ là thích ăn cay thôi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我们以前不太敢吃辣，吃完可能会肚子不舒服\" (Trước đây chúng tôi không dám ăn cay lắm, ăn xong có thể bị khó chịu ở bụng), nên đáp án đúng là vì ăn xong có thể bị khó chịu ở bụng.","options":["因为吃完以后可能会肚子不舒服","因为他们更喜欢吃甜的菜","因为辣的菜在家里很难做","因为医生不让他们吃辣的东西"],"q":"以前王一雪和刘明为什么不太敢吃辣？"},{"answerIdx":1,"explanation":"Trong bài, Lý Văn giải thích \"‘怕不辣’是担心菜还不够辣呢\" (“怕不辣” là lo món ăn vẫn chưa đủ cay đấy), nên đáp án đúng là lo món ăn vẫn chưa đủ cay.","options":["一点儿辣的菜都不敢吃","担心菜还不够辣","吃了辣的菜以后会生病","觉得只有四川菜才算辣"],"q":"根据李文的解释，“怕不辣”是什么意思？"}],"scene":"在刘明和王一雪家，夫妻两人和白家月、李文边吃边聊。","sceneVi":"Tại nhà Lưu Minh và Vương Nhất Tuyết, hai vợ chồng vừa ăn vừa trò chuyện cùng Bạch Gia Nguyệt và Lý Văn."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"周末，白家月、陈天中、李文和安妮聚在一起吃午餐。","pinyin":"Zhōumò, Bái Jiāyuè, Chén Tiānzhōng, Lǐ Wén hé Ānnī jù zài yìqǐ chī wǔcān.","speaker":"Đoạn văn","vi":"Cuối tuần, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và An Ni tụ tập cùng nhau ăn bữa trưa."},{"hanzi":"白家月想吃辣的，要了辣子鸡；陈天中爱吃甜的，想尝尝松鼠鳜鱼；李文更喜欢吃咸的，选了红烧羊肉和一道凉菜；安妮听说贵州酸汤很有名，点了酸汤米线。","pinyin":"Bái Jiāyuè xiǎng chī là de, yào le làzǐjī; Chén Tiānzhōng ài chī tián de, xiǎng chángchang sōngshǔ guìyú; Lǐ Wén gèng xǐhuan chī xián de, xuǎn le hóngshāo yángròu hé yí dào liángcài; Ānnī tīngshuō Guìzhōu suāntāng hěn yǒumíng, diǎn le suāntāng mǐxiàn.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt muốn ăn đồ cay nên gọi gà xào ớt; Trần Thiên Trung thích ăn đồ ngọt nên muốn nếm thử cá quế hình sóc; Lý Văn thích ăn đồ mặn hơn nên chọn thịt dê kho tàu và một món nộm nguội; An Ni nghe nói canh chua Quý Châu rất nổi tiếng nên gọi bún canh chua."},{"hanzi":"他们边吃边聊，非常愉快。","pinyin":"Tāmen biān chī biān liáo, fēicháng yúkuài.","speaker":"Đoạn văn","vi":"Họ vừa ăn vừa trò chuyện, vô cùng vui vẻ."},{"hanzi":"结账时，李文想请客，但大家觉得还是各付各的更合适。","pinyin":"Jiézhàng shí, Lǐ Wén xiǎng qǐngkè, dàn dàjiā juéde háishi gè fù gè de gèng héshì.","speaker":"Đoạn văn","vi":"Khi thanh toán, Lý Văn muốn mời khách, nhưng mọi người cảm thấy vẫn nên ai trả phần nấy thì phù hợp hơn."},{"hanzi":"于是，李文付完钱后，大家把钱转给了他，还笑着说下次再一起聚餐。","pinyin":"Yúshì, Lǐ Wén fùwán qián hòu, dàjiā bǎ qián zhuǎngěi le tā, hái xiàozhe shuō xià cì zài yìqǐ jùcān.","speaker":"Đoạn văn","vi":"Thế là, sau khi Lý Văn trả tiền xong, mọi người chuyển tiền lại cho anh ấy, còn cười nói lần sau sẽ lại cùng nhau đi ăn nữa."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"白家月想吃辣的，要了辣子鸡\" (Bạch Gia Nguyệt muốn ăn cay nên đã gọi món gà xào ớt), nên người gọi món này là Bạch Gia Nguyệt.","options":["陈天中","李文","白家月","安妮"],"q":"谁点了辣子鸡？"},{"answerIdx":2,"explanation":"Trong bài có câu \"于是，李文付完钱后，大家把钱转给了他\" (Thế là sau khi Lý Văn trả tiền xong, mọi người đã chuyển tiền lại cho anh ấy), nên đáp án đúng là Lý Văn trả tiền trước rồi mọi người chuyển tiền cho anh ấy.","options":["李文请大家吃饭，别人没给钱","安妮先付了钱，大家下次再还她","李文先付了钱，之后大家把钱转给了他","陈天中用手机请大家吃了这顿饭"],"q":"吃完饭结账时，他们是怎么付钱的？"}],"scene":"在餐厅里，白家月、陈天中、李文和安妮聚餐。","sceneVi":"Tại nhà hàng, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và An Ni ăn uống tụ tập cùng nhau."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天吃饭的时候，大家坐得比较随意。","pinyin":"Jīntiān chīfàn de shíhou, dàjiā zuò de bǐjiào suíyì.","speaker":"Đoạn văn","vi":"Lúc ăn cơm hôm nay, mọi người ngồi khá thoải mái tùy ý."},{"hanzi":"李文告诉白家月，在中国，正式聚餐和普通聚餐不同，正式聚餐时人们比较重视座位的安排，比如可以按照年龄大小来安排，年龄比较大的客人往往会坐在中间或者面对门口的座位。","pinyin":"Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, zhèngshì jùcān hé pǔtōng jùcān bù tóng, zhèngshì jùcān shí rénmen bǐjiào zhòngshì zuòwèi de ānpái, bǐrú kěyǐ ànzhào niánlíng dàxiǎo lái ānpái, niánlíng bǐjiào dà de kèrén wǎngwǎng huì zuò zài zhōngjiān huòzhě miànduì ménkǒu de zuòwèi.","speaker":"Đoạn văn","vi":"Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, tiệc tụ họp trang trọng và bữa ăn bình thường không giống nhau; khi dự tiệc trang trọng, mọi người khá coi trọng việc sắp xếp chỗ ngồi, ví dụ có thể sắp xếp theo độ tuổi, những vị khách lớn tuổi thường sẽ ngồi ở giữa hoặc ở vị trí đối diện cửa ra vào."},{"hanzi":"大家坐下时，主人会请客人先坐。","pinyin":"Dàjiā zuòxià shí, zhǔrén huì qǐng kèrén xiān zuò.","speaker":"Đoạn văn","vi":"Khi mọi người ngồi xuống, chủ nhà sẽ mời khách ngồi trước."},{"hanzi":"如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin":"Rúguǒ jùcān shí yǒu lǎorén, niánqīngrén yào děng lǎorén zuòxià hòu zài zuò.","speaker":"Đoạn văn","vi":"Nếu khi ăn tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi."},{"hanzi":"白家月听后觉得很有意思，她认为这么做是照顾客人、尊重老人的表现。","pinyin":"Bái Jiāyuè tīnghòu juéde hěn yǒuyìsi, tā rènwéi zhème zuò shì zhàogù kèrén, zūnzhòng lǎorén de biǎoxiàn.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt nghe xong cảm thấy rất thú vị, cô ấy cho rằng làm như vậy là biểu hiện của sự quan tâm khách và tôn trọng người lớn tuổi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"年龄比较大的客人往往会坐在中间或者面对门口的座位\" (Những vị khách lớn tuổi hơn thường sẽ ngồi ở giữa hoặc ở chỗ đối diện cửa ra vào), nên đáp án đúng là chỗ ở giữa hoặc đối diện cửa ra vào.","options":["靠近厨房或者角落的座位","中间或者面对门口的座位","背对门口或者最边上的座位","离主人最远的那个座位"],"q":"在中国正式聚餐时，年龄比较大的客人往往坐在哪里？"},{"answerIdx":3,"explanation":"Trong bài có câu \"如果聚餐时有老人，年轻人要等老人坐下后再坐\" (Nếu khi tụ họp ăn uống có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi), nên đáp án đúng là đợi người lớn tuổi ngồi xuống rồi mới ngồi.","options":["一进餐厅就马上找座位坐下","在主人还没有到的时候先坐下","等所有客人都点完菜以后再坐","等老人坐下以后再坐下"],"q":"如果聚餐时有老人，年轻人应该什么时候坐下？"}],"scene":"中国餐桌上的座位安排","sceneVi":"Sắp xếp chỗ ngồi trên bàn ăn Trung Quốc"}],"hsk4a-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，李文，我身体不舒服。","pinyin":"Wèi, Lǐ Wén, wǒ shēntǐ bù shūfu.","speaker":"白家月","vi":"Alo, Lý Văn, mình thấy trong người không khỏe."},{"hanzi":"你怎么了？听你的声音，好像感冒了。","pinyin":"Nǐ zěnme le? Tīng nǐ de shēngyīn, hǎoxiàng gǎnmào le.","speaker":"李文","vi":"Cậu bị sao thế? Nghe giọng cậu hình như bị cảm rồi."},{"hanzi":"对，我还发烧，一直咳嗽，咳得很厉害。","pinyin":"Duì, wǒ hái fāshāo, yìzhí késou, ké de hěn lìhai.","speaker":"白家月","vi":"Đúng vậy, mình còn bị sốt, ho liên tục, ho rất dữ dội."},{"hanzi":"那挺严重的，最好赶快去医院检查一下。","pinyin":"Nà tǐng yánzhòng de, zuìhǎo gǎnkuài qù yīyuàn jiǎnchá yíxià.","speaker":"李文","vi":"Vậy thì khá nghiêm trọng đấy, tốt nhất mau đi bệnh viện kiểm tra một chút đi."},{"hanzi":"我也这么想，不过我来中国后还没去过医院，不知道怎么在中国的医院看病。","pinyin":"Wǒ yě zhème xiǎng, búguò wǒ lái Zhōngguó hòu hái méi qùguo yīyuàn, bù zhīdào zěnme zài Zhōngguó de yīyuàn kànbìng.","speaker":"白家月","vi":"Mình cũng nghĩ vậy, nhưng từ khi đến Trung Quốc mình vẫn chưa đi bệnh viện bao giờ, không biết cách khám bệnh ở bệnh viện Trung Quốc."},{"hanzi":"没关系，我陪你一起去，还能帮你翻译。你在家等一下，我现在就去接你。","pinyin":"Méi guānxi, wǒ péi nǐ yìqǐ qù, hái néng bāng nǐ fānyì. Nǐ zài jiā děng yíxià, wǒ xiànzài jiù qù jiē nǐ.","speaker":"李文","vi":"Không sao đâu, mình đi cùng với cậu, còn có thể giúp cậu phiên dịch. Cậu ở nhà đợi một chút, bây giờ mình sang đón cậu ngay."},{"hanzi":"太好了！有你陪着，我就放心多了。","pinyin":"Tài hǎo le! Yǒu nǐ péizhe, wǒ jiù fàngxīn duō le.","speaker":"白家月","vi":"Tuyệt quá! Có cậu đi cùng, mình yên tâm hơn nhiều rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn đoán \"好像感冒了\" (hình như bị cảm rồi) và Bạch Gia Nguyệt nói thêm \"对，我还发烧，一直咳嗽，咳得很厉害\" (Đúng vậy, mình còn bị sốt, ho liên tục, ho rất dữ dội), nên cô ấy bị cảm, sốt và ho liên tục.","options":["肚子疼，而且有点儿拉肚子","感冒、发烧，还一直咳嗽","眼睛很疼，晚上睡不着觉","腿受伤了，没办法自己走路"],"q":"白家月现在身体怎么了？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"不过我来中国后还没去过医院，不知道怎么在中国的医院看病\" (nhưng từ khi đến Trung Quốc mình chưa từng đi bệnh viện, không biết khám bệnh ở bệnh viện Trung Quốc như thế nào), nên cô ấy lo lắng vì chưa từng đến bệnh viện Trung Quốc và không biết cách khám.","options":["她担心去医院看病要花很多钱","她害怕一个人打针会特别疼","她没去过中国的医院，不知道怎么看病","她家里离医院太远，没有车去"],"q":"关于去医院看病，白家月一开始担心什么？"}],"scene":"在家里，白家月躺在床上给李文打电话。","sceneVi":"Ở nhà, Bạch Gia Nguyệt nằm trên giường gọi điện thoại cho Lý Văn."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"护士，您好，我的这位外国朋友生病了，第一次来这里看病，需要怎么做？","pinyin":"Hùshi, nín hǎo, wǒ de zhè wèi wàiguó péngyou shēngbìng le, dì-yī cì lái zhèlǐ kànbìng, xūyào zěnme zuò?","speaker":"李文","vi":"Chào y tá, bạn người nước ngoài này của tôi bị ốm, lần đầu tiên đến đây khám bệnh, cần phải làm như thế nào ạ?"},{"hanzi":"请在这张表上写上病人的姓名、性别、国籍、年龄、电话号码和家庭地址。","pinyin":"Qǐng zài zhè zhāng biǎo shang xiěshàng bìngrén de xìngmíng, xìngbié, guójí, niánlíng, diànhuà hàomǎ hé jiātíng dìzhǐ.","speaker":"护士","vi":"Xin hãy điền họ tên, giới tính, quốc tịch, tuổi, số điện thoại và địa chỉ nhà của bệnh nhân vào tờ đơn này."},{"hanzi":"我写好了，您看看，这样可以吗？","pinyin":"Wǒ xiěhǎo le, nín kànkan, zhèyàng kěyǐ ma?","speaker":"李文","vi":"Tôi viết xong rồi, cô xem thử xem, như vậy được chưa ạ?"},{"hanzi":"没问题，您拿着病人的护照去挂号吧。","pinyin":"Méi wèntí, nín názhe bìngrén de hùzhào qù guàhào ba.","speaker":"护士","vi":"Không vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám đi ạ."},{"hanzi":"家月，我去排队挂号，你先在大厅休息，别着急。","pinyin":"Jiāyuè, wǒ qù páiduì guàhào, nǐ xiān zài dàtīng xiūxi, bié zháojí.","speaker":"李文","vi":"Gia Nguyệt, mình đi xếp hàng lấy số khám đây, cậu cứ ở sảnh nghỉ ngơi trước đi, đừng sốt ruột nhé."},{"hanzi":"好的，真是太谢谢你了！","pinyin":"Hǎo de, zhēn shì tài xièxie nǐ le!","speaker":"白家月","vi":"Được rồi, thật sự cảm ơn cậu nhiều lắm!"},{"hanzi":"你跟我有什么好客气的。","pinyin":"Nǐ gēn wǒ yǒu shénme hǎo kèqi de.","speaker":"李文","vi":"Cậu với mình thì có gì mà phải khách sáo chứ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, y tá bảo Lý Văn \"没问题，您拿着病人的护照去挂号吧\" (Không vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám nhé), nên đáp án đúng là cầm hộ chiếu của bệnh nhân đi đăng ký khám.","options":["带着白家月直接进医生办公室","先去药店买一些感冒药","拿着病人的护照去挂号","在大厅里再填另外一张表"],"q":"填好表以后，护士让李文接着做什么？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn dặn Bạch Gia Nguyệt \"我去排队挂号，你先在大厅休息，别着急\" (Mình đi xếp hàng đăng ký khám, bạn cứ ở đại sảnh nghỉ ngơi trước, đừng lo lắng), nên Bạch Gia Nguyệt nghỉ ngơi ở đại sảnh.","options":["在大厅里休息","在门口等出租车","在房间里做检查","自己去拿药"],"q":"李文去排队挂号的时候，白家月在哪里做什么？"}],"scene":"在医院大厅，李文帮白家月办理看病手续。","sceneVi":"Tại sảnh lớn bệnh viện, Lý Văn giúp Bạch Gia Nguyệt làm thủ tục khám bệnh."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"下午白家月去看病了，她告诉医生，自己平时身体不错，偶尔才会生一次病。","pinyin":"Xiàwǔ Bái Jiāyuè qù kànbìng le, tā gàosu yīshēng, zìjǐ píngshí shēntǐ búcuò, ǒu'ěr cái huì shēng yí cì bìng.","speaker":"Đoạn văn","vi":"Buổi chiều Bạch Gia Nguyệt đi khám bệnh, cô ấy nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị ốm một lần."},{"hanzi":"这次她病得很厉害，头也一直疼，身上一点儿力气都没有。","pinyin":"Zhè cì tā bìng de hěn lìhai, tóu yě yìzhí téng, shēnshang yìdiǎnr lìqi dōu méiyǒu.","speaker":"Đoạn văn","vi":"Lần này cô ấy ốm rất nặng, đầu cũng đau liên tục, trên người không còn chút sức lực nào."},{"hanzi":"医生给她做了检查，检查结果出来后，发现她得了比较严重的流行性感冒。","pinyin":"Yīshēng gěi tā zuò le jiǎnchá, jiǎnchá jiéguǒ chūlái hòu, fāxiàn tā dé le bǐjiào yánzhòng de liúxíngxìng gǎnmào.","speaker":"Đoạn văn","vi":"Bác sĩ kiểm tra cho cô ấy, sau khi có kết quả kiểm tra thì phát hiện cô ấy bị cúm khá nặng."},{"hanzi":"医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效。","pinyin":"Yīshēng gàosu tā, xiànzài xūyào bǎ tǐwēn jiàng xiàlái, guāng chīyào kǒngpà búgòu, dǎzhēn huì gèng yǒuxiào.","speaker":"Đoạn văn","vi":"Bác sĩ bảo cô ấy rằng hiện tại cần phải hạ thân nhiệt xuống, chỉ uống thuốc e rằng không đủ, tiêm sẽ có hiệu quả hơn."},{"hanzi":"医生还让她回家以后按时吃药，多喝水，多休息。","pinyin":"Yīshēng hái ràng tā huíjiā yǐhòu ànshí chīyào, duō hē shuǐ, duō xiūxi.","speaker":"Đoạn văn","vi":"Bác sĩ còn dặn cô ấy sau khi về nhà phải uống thuốc đúng giờ, uống nhiều nước và nghỉ ngơi nhiều."},{"hanzi":"晚上，白家月睡觉时出了一身汗。","pinyin":"Wǎnshang, Bái Jiāyuè shuìjiào shí chū le yì shēn hàn.","speaker":"Đoạn văn","vi":"Buổi tối, khi Bạch Gia Nguyệt ngủ đã toát mồ hôi đầy người."},{"hanzi":"第二天醒来时，她感觉头不那么疼了，体温也低了一些，身体不那么难受了。","pinyin":"Dì-èr tiān xǐnglái shí, tā gǎnjué tóu bú nàme téng le, tǐwēn yě dī le yìxiē, shēntǐ bú nàme nánshòu le.","speaker":"Đoạn văn","vi":"Ngày hôm sau lúc tỉnh dậy, cô ấy cảm thấy đầu không còn đau như thế nữa, nhiệt độ cơ thể cũng giảm đi một chút, trong người không còn khó chịu như vậy nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"检查结果出来后，发现她得了比较严重的流行性感冒\" (Sau khi có kết quả kiểm tra, phát hiện cô ấy bị cúm mùa khá nặng), nên đáp án đúng là bị cúm mùa khá nặng.","options":["普通的胃病","比较严重的流行性感冒","一点儿小问题，不用吃药","吃坏东西引起的肚子疼"],"q":"检查结果出来后，医生发现白家月得了什么病？"},{"answerIdx":2,"explanation":"Trong bài có câu \"医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效\" (Bác sĩ bảo cô ấy hiện cần hạ thân nhiệt xuống, chỉ uống thuốc e rằng không đủ, tiêm sẽ hiệu quả hơn), nên đáp án đúng là cần hạ sốt và chỉ uống thuốc có thể chưa đủ, tiêm hiệu quả hơn.","options":["因为她害怕吃药，不想吃药","因为医院那天刚好没有感冒药了","因为需要把体温降下来，只吃药可能不够，打针更有效","因为医生觉得打针以后就不用回家休息了"],"q":"为什么医生建议白家月打针？"}],"scene":"一次看病的经历","sceneVi":"Một lần đi khám bệnh"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"外国人第一次在中国看病，可能会担心语言不通，或者觉得看病的过程和自己的国家不同。","pinyin":"Wàiguórén dì-yī cì zài Zhōngguó kànbìng, kěnéng huì dānxīn yǔyán bù tōng, huòzhě juéde kànbìng de guòchéng hé zìjǐ de guójiā bù tóng.","speaker":"Đoạn văn","vi":"Người nước ngoài lần đầu tiên đi khám bệnh ở Trung Quốc có thể sẽ lo lắng bất đồng ngôn ngữ, hoặc cảm thấy quy trình khám bệnh khác với đất nước của mình."},{"hanzi":"其实，这些问题都有办法解决。","pinyin":"Qíshí, zhèxiē wèntí dōu yǒu bànfǎ jiějué.","speaker":"Đoạn văn","vi":"Thực ra, những vấn đề này đều có cách giải quyết."},{"hanzi":"有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高。","pinyin":"Yǒude yīyuàn yǒu guójìbù, nàlǐ de yīshēng yìbān huì shuō Yīngwén, jiāoliú bǐjiào fāngbiàn, dànshì guójìbù de shōufèi bǐjiào gāo.","speaker":"Đoạn văn","vi":"Có những bệnh viện có khoa Quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí ở khoa Quốc tế tương đối cao."},{"hanzi":"如果没有特别需要，可以选择普通部，用简单的中文和医生交流。","pinyin":"Rúguǒ méiyǒu tèbié xūyào, kěyǐ xuǎnzé pǔtōngbù, yòng jiǎndān de Zhōngwén hé yīshēng jiāoliú.","speaker":"Đoạn văn","vi":"Nếu không có nhu cầu đặc biệt, có thể chọn khoa thông thường, dùng tiếng Trung đơn giản để trao đổi với bác sĩ."},{"hanzi":"在中国看病要先挂号，然后再去找医生。","pinyin":"Zài Zhōngguó kànbìng yào xiān guàhào, ránhòu zài qù zhǎo yīshēng.","speaker":"Đoạn văn","vi":"Đi khám bệnh ở Trung Quốc phải đăng ký lấy số trước, sau đó mới đi gặp bác sĩ."},{"hanzi":"医生会问病人的情况，有时还会做一些检查，好给出合适的治疗方法。","pinyin":"Yīshēng huì wèn bìngrén de qíngkuàng, yǒushí hái huì zuò yìxiē jiǎnchá, hǎo gěichū héshì de zhìliáo fāngfǎ.","speaker":"Đoạn văn","vi":"Bác sĩ sẽ hỏi tình hình của bệnh nhân, đôi khi còn làm một số xét nghiệm kiểm tra để đưa ra phương pháp điều trị phù hợp."},{"hanzi":"只要按照医生说的一步一步来，一般都可以顺利得到治疗。","pinyin":"Zhǐyào ànzhào yīshēng shuō de yíbù yíbù lái, yìbān dōu kěyǐ shùnlì dédào zhìliáo.","speaker":"Đoạn văn","vi":"Chỉ cần làm từng bước một theo lời bác sĩ dặn, nhìn chung đều có thể được điều trị thuận lợi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高\" (Có bệnh viện có khoa Quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí ở khoa Quốc tế khá cao), nên nhược điểm là mức phí khám chữa bệnh khá cao.","options":["那里的医生一般不会说英文","看病的收费比较高","病人不能在那里做检查","挂号的过程特别慢"],"q":"根据课文，医院的国际部有什么缺点？"},{"answerIdx":2,"explanation":"Trong bài có câu \"在中国看病要先挂号，然后再去找医生\" (Khám bệnh ở Trung Quốc phải đăng ký khám trước, rồi mới đi gặp bác sĩ), nên đáp án đúng là đăng ký khám trước rồi mới gặp bác sĩ.","options":["先做检查，再挂号找医生","先找医生开药，再填写表格","先挂号，然后再去找医生","先交钱治疗，再问医生情况"],"q":"在中国看病，一般应该先做什么，再做什么？"}],"scene":"怎么在中国看病","sceneVi":"Cách đi khám bệnh ở Trung Quốc"}],"hsk4a-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"经理，打扰您一下。市场调查的计划书我昨天发到您邮箱了。在内容方面，您觉得有需要改的吗？","pinyin":"Jīnglǐ, dǎrǎo nín yíxià. Shìchǎng diàochá de jìhuàshū wǒ zuótiān fā dào nín yóuxiāng le. Zài nèiróng fāngmiàn, nín juéde yǒu xūyào gǎi de ma?","speaker":"同事","vi":"Giám đốc, xin phép làm phiền chị một chút. Bản kế hoạch khảo sát thị trường tôi đã gửi vào hộp thư của chị hôm qua rồi. Về mặt nội dung, chị thấy có chỗ nào cần sửa không ạ?"},{"hanzi":"我看过了，写得不错，就是调查的地点只有超市，不太够。","pinyin":"Wǒ kànguo le, xiě de búcuò, jiùshì diàochá de dìdiǎn zhǐ yǒu chāoshì, bú tài gòu.","speaker":"王一雪","vi":"Tôi xem rồi, viết khá tốt, chỉ là địa điểm khảo sát chỉ có siêu thị thì hơi ít."},{"hanzi":"好的，那我再加一些网店。","pinyin":"Hǎo de, nà wǒ zài jiā yìxiē wǎngdiàn.","speaker":"同事","vi":"Vâng, vậy tôi sẽ thêm một số cửa hàng trực tuyến nữa ạ."},{"hanzi":"行。做调查的时候要细心，注意了解客户真正的想法。","pinyin":"Xíng. Zuò diàochá de shíhou yào xìxīn, zhùyì liǎojiě kèhù zhēnzhèng de xiǎngfǎ.","speaker":"王一雪","vi":"Được. Khi làm khảo sát phải cẩn thận, chú ý tìm hiểu suy nghĩ thực sự của khách hàng."},{"hanzi":"明白了，我会认真准备，按时完成任务。","pinyin":"Míngbai le, wǒ huì rènzhēn zhǔnbèi, ànshí wánchéng rènwù.","speaker":"同事","vi":"Tôi hiểu rồi ạ, tôi sẽ chuẩn bị nghiêm túc và hoàn thành nhiệm vụ đúng hạn."},{"hanzi":"嗯，如果遇到什么问题，及时跟我联系。","pinyin":"Ǹg, rúguǒ yùdào shénme wèntí, jíshí gēn wǒ liánxì.","speaker":"王一雪","vi":"Ừ, nếu gặp vấn đề gì thì liên hệ kịp thời với tôi nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nhận xét \"我看过了，写得不错，就是调查的地点只有超市，不太够\" (Tôi xem rồi, viết khá tốt, chỉ là địa điểm khảo sát chỉ có siêu thị thì chưa đủ lắm), nên đáp án đúng là viết khá tốt nhưng địa điểm khảo sát quá ít, chỉ có siêu thị.","options":["整体写得不错，但调查地点太少，只有超市","内容写得不好，需要全部重写一遍","调查地点太多了，应该去掉网店","她还没有时间看同事发来的邮件"],"q":"王一雪觉得同事写的市场调查计划书怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết dặn \"做调查的时候要细心，注意了解客户真正的想法\" (Khi làm khảo sát phải tỉ mỉ, chú ý tìm hiểu suy nghĩ thực sự của khách hàng), nên đáp án đúng là cần tỉ mỉ, chú ý tìm hiểu suy nghĩ thực sự của khách hàng.","options":["尽量少花时间，早点儿结束调查","只在超市里问买东西的人","要细心，注意了解客户真正的想法","不用和经理联系，自己决定就行"],"q":"王一雪提醒同事做调查时要注意什么？"}],"scene":"在王一雪办公室，同事向她汇报工作。","sceneVi":"Tại văn phòng của Vương Nhất Tuyết, đồng nghiệp đang báo cáo công việc với cô ấy."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"杨哥，经理让我下周去上海出差，做市场调查，你有这方面的经验吗？","pinyin":"Yáng gē, jīnglǐ ràng wǒ xià zhōu qù Shànghǎi chūchāi, zuò shìchǎng diàochá, nǐ yǒu zhè fāngmiàn de jīngyàn ma?","speaker":"同事","vi":"Anh Dương ơi, giám đốc bảo tôi tuần sau đi Thượng Hải công tác để làm khảo sát thị trường, anh có kinh nghiệm về mặt này không?"},{"hanzi":"你要去几天？主要调查什么内容？","pinyin":"Nǐ yào qù jǐ tiān? Zhǔyào diàochá shénme nèiróng?","speaker":"杨同乐","vi":"Em đi mấy ngày? Chủ yếu khảo sát những nội dung gì?"},{"hanzi":"去四天，打算采访一些客户，了解他们对新产品的看法。","pinyin":"Qù sì tiān, dǎsuàn cǎifǎng yìxiē kèhù, liǎojiě tāmen duì xīn chǎnpǐn de kànfǎ.","speaker":"同事","vi":"Đi bốn ngày ạ, em dự định phỏng vấn một số khách hàng để tìm hiểu quan điểm của họ về sản phẩm mới."},{"hanzi":"那你要提前准备好问题，便于和客户交流。","pinyin":"Nà nǐ yào tíqián zhǔnbèi hǎo wèntí, biànyú hé kèhù jiāoliú.","speaker":"杨同乐","vi":"Vậy em phải chuẩn bị sẵn câu hỏi trước, để tiện trao đổi với khách hàng."},{"hanzi":"好的，我已经准备了一些问题。","pinyin":"Hǎo de, wǒ yǐjīng zhǔnbèi le yìxiē wèntí.","speaker":"同事","vi":"Vâng, em cũng đã chuẩn bị sẵn một số câu hỏi rồi ạ."},{"hanzi":"很好。既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":"Hěn hǎo. Jìrán chūchāi shíjiān bù cháng, jiù yào ānpái hǎo shíjiān, duō huòdé yǒuyòng de xìnxī.","speaker":"杨同乐","vi":"Tốt lắm. Đã đi công tác thời gian không dài thì phải sắp xếp thời gian hợp lý, thu thập thật nhiều thông tin hữu ích."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, người đồng nghiệp nói \"去四天，打算采访一些客户，了解他们对新产品的看法\" (Đi bốn ngày, dự định phỏng vấn một số khách hàng để tìm hiểu nhận xét của họ về sản phẩm mới), nên mục đích chính là phỏng vấn khách hàng về sản phẩm mới.","options":["参加一个重要的公司会议","拜访以前的老朋友","采访客户，了解他们对新产品的看法","去上海的分公司学习管理方法"],"q":"同事下周去上海出差四天，主要打算做什么？"},{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Lạc đưa ra hai lời khuyên: \"那你要提前准备好问题，便于和客户交流\" (Vậy cậu phải chuẩn bị sẵn câu hỏi trước để tiện trao đổi với khách hàng) và \"就要安排好时间，多获得有用的信息\" (nên sắp xếp thời gian hợp lý, thu thập nhiều thông tin hữu ích), nên đáp án đúng là chuẩn bị trước câu hỏi và sắp xếp thời gian hợp lý để thu thập nhiều thông tin hữu ích.","options":["延长出差时间，并多带几个同事一起去","提前准备好问题，同时安排好时间以多获得有用信息","不要提前准备问题，到了上海再慢慢想","先去了解一下上海的超市，不用见客户"],"q":"杨同乐给了同事什么建议？"}],"scene":"在公司，同事向杨同乐征求建议。","sceneVi":"Tại công ty, đồng nghiệp xin lời khuyên của Dương Đồng Lạc."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"前段时间，杨同乐的同事谈成了一笔不错的生意。","pinyin":"Qián duàn shíjiān, Yáng Tónglè de tóngshì tánchéng le yì bǐ búcuò de shēngyi.","speaker":"Đoạn văn","vi":"Thời gian trước, đồng nghiệp của Dương Đồng Lạc đã đàm phán thành công một thương vụ khá tốt."},{"hanzi":"刚开始，这位同事也遇到了一些困难。","pinyin":"Gāng kāishǐ, zhè wèi tóngshì yě yùdào le yìxiē kùnnan.","speaker":"Đoạn văn","vi":"Lúc mới bắt đầu, người đồng nghiệp này cũng gặp phải một số khó khăn."},{"hanzi":"拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","pinyin":"Ná hé kèhù jiāoliú lái shuō, suīrán tā néng bǎ chǎnpǐn de yōuquēdiǎn shuō de hěn qīngchu, dàn shíjì xiàoguǒ bìng bù lǐxiǎng.","speaker":"Đoạn văn","vi":"Nói riêng về việc giao tiếp với khách hàng, mặc dù cô ấy có thể nói rất rõ ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không được như ý."},{"hanzi":"杨同乐告诉她，这是因为她介绍的方式都一样。","pinyin":"Yáng Tónglè gàosu tā, zhè shì yīnwèi tā jièshào de fāngshì dōu yíyàng.","speaker":"Đoạn văn","vi":"Dương Đồng Lạc nói với cô ấy rằng đó là vì cách giới thiệu của cô ấy đều giống nhau."},{"hanzi":"其实，不同年龄、不同性别的客户对产品的关注点是不一样的。","pinyin":"Qíshí, bùtóng niánlíng, bùtóng xìngbié de kèhù duì chǎnpǐn de guānzhùdiǎn shì bù yíyàng de.","speaker":"Đoạn văn","vi":"Thực ra, khách hàng ở các độ tuổi và giới tính khác nhau sẽ có những điểm quan tâm khác nhau đối với sản phẩm."},{"hanzi":"于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。","pinyin":"Yúshì, zhè wèi tóngshì yòu rènzhēn de jìnxíng le jǐ cì shìchǎng diàochá, liǎojiě bùtóng kèhù de xiǎngfǎ.","speaker":"Đoạn văn","vi":"Thế là người đồng nghiệp này lại nghiêm túc tiến hành thêm vài lần khảo sát thị trường để tìm hiểu suy nghĩ của các khách hàng khác nhau."},{"hanzi":"后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多。","pinyin":"Hòulái tā zài miànduì bùtóng kèhù shí, néng gēnjù tāmen de qíngkuàng jièshào chǎnpǐn, xiàoguǒ yíxià jiù hǎo le hěn duō.","speaker":"Đoạn văn","vi":"Sau này khi đối diện với những khách hàng khác nhau, cô ấy đã có thể giới thiệu sản phẩm dựa theo tình hình của họ, hiệu quả lập tức tốt hơn rất nhiều."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"杨同乐告诉她，这是因为她介绍的方式都一样\" (Dương Đồng Lạc nói với cô ấy, đó là vì cách giới thiệu của cô ấy đều giống nhau), nên nguyên nhân là vì cô ấy giới thiệu sản phẩm theo cùng một cách với mọi khách hàng.","options":["因为她自己也不清楚产品的优缺点","因为她对所有客户都用一样的方式介绍产品","因为公司的产品质量不太好，价格太高","因为她说话太快，客户听不明白"],"q":"刚开始，为什么这位同事和客户交流时实际效果不理想？"},{"answerIdx":2,"explanation":"Trong bài có câu \"于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多\" (Vì thế, người đồng nghiệp này lại nghiêm túc làm vài cuộc khảo sát thị trường... Sau đó khi gặp các khách hàng khác nhau, cô ấy có thể giới thiệu sản phẩm tùy theo tình hình của họ, hiệu quả lập tức tốt hơn nhiều), nên đáp án đúng là cô ấy làm lại khảo sát thị trường và giới thiệu sản phẩm phù hợp theo từng đối tượng khách hàng.","options":["她换了一家新公司，去卖别的产品","她请杨同乐帮她去和客户谈生意","她重新做了市场调查，并根据不同客户的情况来介绍产品","她决定只和年龄相同的客户交流"],"q":"为了提高效果，这位同事后来是怎么做的？"}],"scene":"不同客户，不同方法","sceneVi":"Khách hàng khác nhau, phương pháp khác nhau"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"有的年轻人经常换工作，总觉得下一份工作会更好。","pinyin":"Yǒude niánqīngrén jīngcháng huàn gōngzuò, zǒng juéde xià yí fèn gōngzuò huì gèng hǎo.","speaker":"Đoạn văn","vi":"Một số người trẻ thường xuyên đổi việc, luôn cảm thấy công việc tiếp theo sẽ tốt hơn."},{"hanzi":"但是，适应新工作往往需要比较长的时间。","pinyin":"Dànshì, shìyìng xīn gōngzuò wǎngwǎng xūyào bǐjiào cháng de shíjiān.","speaker":"Đoạn văn","vi":"Tuy nhiên, việc thích nghi với công việc mới thường cần một khoảng thời gian khá dài."},{"hanzi":"如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响。","pinyin":"Rúguǒ zǒngshì huàn gōngzuò, búdàn hěn nán jīlěi jīngyàn, hái kěnéng huì shǐ zìjǐ de fāzhǎn shòudào yǐngxiǎng.","speaker":"Đoạn văn","vi":"Nếu cứ liên tục đổi việc, không những rất khó tích lũy kinh nghiệm mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng."},{"hanzi":"我认为，年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。","pinyin":"Wǒ rènwéi, niánqīngrén gāng jìnrù shèhuì shí, bù néng zhǐ guānxīn gōngzī de gāodī, gèng yào zhòngshì xuéxí.","speaker":"Đoạn văn","vi":"Tôi cho rằng, khi người trẻ mới bước chân vào xã hội, không thể chỉ quan tâm đến mức lương cao hay thấp, mà càng phải coi trọng việc học hỏi."},{"hanzi":"比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。","pinyin":"Bǐrú, xuéxí kèběn zhōng méiyǒu de zhuānyè zhīshi, liǎojiě gōngsī de guǎnlǐ fāngshì, xuéhuì hé tóngshì yǒuxiào jiāoliú, děngděng.","speaker":"Đoạn văn","vi":"Ví dụ như học những kiến thức chuyên môn không có trong sách giáo khoa, tìm hiểu cách thức quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp, v.v."},{"hanzi":"只有把这些基础打好，提高工作能力，今后才会有更好的发展机会。","pinyin":"Zhǐyǒu bǎ zhèxiē jīchǔ dǎ hǎo, tígāo gōngzuò nénglì, jīnhòu cái huì yǒu gèng hǎo de fāzhǎn jīhuì.","speaker":"Đoạn văn","vi":"Chỉ khi xây dựng vững chắc những nền tảng này và nâng cao năng lực làm việc, sau này mới có những cơ hội phát triển tốt hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响\" (Nếu cứ luôn đổi việc, không những khó tích lũy kinh nghiệm mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng), nên đáp án đúng là khó tích lũy kinh nghiệm và có thể ảnh hưởng đến sự phát triển bản thân.","options":["会变得越来越不喜欢学习新知识","很难积累经验，还可能影响自己的发展","没有时间去认识新公司的同事","工资一定会比以前低很多"],"q":"根据课文，年轻人如果经常换工作，可能会有什么坏处？"},{"answerIdx":2,"explanation":"Trong bài có câu \"年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。只有把这些基础打好...\" (Người trẻ mới bước vào xã hội không thể chỉ quan tâm lương cao thấp mà càng phải coi trọng việc học, ví dụ học kiến thức chuyên môn không có trong sách vở, tìm hiểu cách quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp... Chỉ khi xây dựng tốt nền tảng này...), nên đáp án đúng là coi trọng việc học kiến thức chuyên môn, cách quản lý và giao tiếp với đồng nghiệp để xây dựng nền tảng.","options":["尽量找一份工资最高、最轻松的工作","在一年内多换几份工作，看看自己喜欢什么","重视学习专业知识、管理方式和与同事交流，打好基础","只学好学校课本里的知识就足够了"],"q":"作者认为年轻人刚进入社会时，最应该重视什么？"}],"scene":"工作的选择与发展","sceneVi":"Lựa chọn và phát triển công việc"}],"hsk4a-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，最近学习太紧张了，咱们明天出去放松放松吧。","pinyin":"Jiāyuè, zuìjìn xuéxí tài jǐnzhāng le, zánmen míngtiān chūqù fàngsōng fàngsōng ba.","speaker":"安妮","vi":"Gia Nguyệt à, dạo này học hành căng thẳng quá, ngày mai chúng mình ra ngoài thư giãn một chút đi."},{"hanzi":"呀，正好我也想出去呢。咱们去哪儿好呢？","pinyin":"Yā, zhènghǎo wǒ yě xiǎng chūqù ne. Zánmen qù nǎr hǎo ne?","speaker":"白家月","vi":"Ôi, đúng lúc mình cũng muốn ra ngoài đây. Chúng mình đi đâu thì hay nhỉ?"},{"hanzi":"不管去哪儿，能放松的地方都行。","pinyin":"Bùguǎn qù nǎr, néng fàngsōng de dìfang dōu xíng.","speaker":"安妮","vi":"Bất kể đi đâu, chỗ nào thư giãn được đều ổn cả."},{"hanzi":"郊区怎么样？","pinyin":"Jiāoqū zěnmeyàng?","speaker":"白家月","vi":"Vùng ngoại ô thì sao?"},{"hanzi":"天中说，下周王老师要带咱们去郊区游玩呢。","pinyin":"Tiānzhōng shuō, xià zhōu Wáng lǎoshī yào dài zánmen qù jiāoqū yóuwán ne.","speaker":"安妮","vi":"Thiên Trung bảo tuần sau thầy Vương sẽ dẫn chúng mình đi ngoại ô tham quan đấy."},{"hanzi":"是吗？那咱们明天去爬长城吧，不是说“不到长城非好汉”吗？","pinyin":"Shì ma? Nà zánmen míngtiān qù pá Chángchéng ba, bú shì shuō “bú dào Chángchéng fēi hǎohàn” ma?","speaker":"白家月","vi":"Thế à? Vậy ngày mai chúng mình đi leo Vạn Lý Trường Thành đi, chẳng phải có câu 'Bất đáo Trường Thành phi hảo hán' sao?"},{"hanzi":"好主意！不过明天是个大晴天，外出记得戴帽子。","pinyin":"Hǎo zhǔyi! Búguò míngtiān shì ge dà qíngtiān, wàichū jìde dài màozi.","speaker":"安妮","vi":"Ý hay đấy! Nhưng ngày mai trời nắng to, ra ngoài nhớ đội mũ nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Bạch Gia Nguyệt gợi ý đi ngoại ô, Anny nói \"天中说，下周王老师要带咱们去郊区游玩呢\" (Thiên Trung nói tuần sau thầy Vương sẽ dẫn chúng mình đi chơi ở ngoại ô đấy), nên hai người không đi ngoại ô vào ngày mai.","options":["因为郊区太远，明天来不及回来","因为下周王老师要带她们去郊区游玩","因为明天要下雨，不适合去郊区","因为她们以前已经去过好几次郊区了"],"q":"为什么安妮和白家月明天不去郊区玩？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt đề nghị \"那咱们明天去爬长城吧\" (Vậy ngày mai chúng mình đi leo Trường Thành đi) và Anny đồng ý rồi nhắc \"不过明天是个大晴天，外出记得戴帽子\" (Nhưng ngày mai trời nắng to đấy, ra ngoài nhớ đội mũ nhé), nên đáp án đúng là đi leo Trường Thành và nhớ đội mũ.","options":["去公园散步，安妮提醒她多带点儿水","在宿舍休息，安妮提醒她早点儿睡觉","去爬长城，安妮提醒她明天是大晴天，记得戴帽子","去郊区爬山，安妮提醒她穿舒服的鞋"],"q":"两人最后决定明天去做什么？安妮还提醒白家月什么？"}],"scene":"周五晚上，安妮给白家月打电话。","sceneVi":"Tối thứ Sáu, Anny gọi điện thoại cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"同乐哥，你们平时工作忙吗？","pinyin":"Tónglè gē, nǐmen píngshí gōngzuò máng ma?","speaker":"李文","vi":"Anh Đồng Lạc, bình thường công việc của mọi người có bận không?"},{"hanzi":"挺忙的。以前我总觉得年轻时要多学多干，所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯。","pinyin":"Tǐng máng de. Yǐqián wǒ zǒng juéde niánqīng shí yào duō xué duō gàn, suǒyǐ cānjiā le gōngsī lǐ de hěn duō xiàngmù, jīngcháng jiābān, áoyè, shēntǐ yě liàngqǐ le hóngdēng.","speaker":"杨同乐","vi":"Khá bận đấy. Trước đây anh luôn nghĩ khi còn trẻ thì phải học nhiều làm nhiều, nên đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, cơ thể cũng bật đèn đỏ (báo động sức khỏe) luôn."},{"hanzi":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":"Háishi bié gěi zìjǐ tài dà yālì, fǒuzé, shīqù jiànkāng jiù bù zhídé le.","speaker":"李文","vi":"Tốt nhất đừng tự tạo áp lực quá lớn cho bản thân, nếu không, đánh mất sức khỏe thì thật không đáng chút nào."},{"hanzi":"是啊，后来我就不接那么多项目了。我发现暂停下来、好好休息之后，我能把工作做得更快更好。","pinyin":"Shì a, hòulái wǒ jiù bù jiē nàme duō xiàngmù le. Wǒ fāxiàn zàntíng xiàlái, hǎohāo xiūxi zhīhòu, wǒ néng bǎ gōngzuò zuò de gèng kuài gèng hǎo.","speaker":"杨同乐","vi":"Đúng vậy, sau này anh không nhận nhiều dự án như thế nữa. Anh nhận ra sau khi tạm dừng lại và nghỉ ngơi đầy đủ, anh có thể làm việc nhanh hơn và tốt hơn."},{"hanzi":"对，该工作时就工作，该放松时就要放松。","pinyin":"Duì, gāi gōngzuò shí jiù gōngzuò, gāi fàngsōng shí jiù yào fàngsōng.","speaker":"李文","vi":"Đúng thế, lúc cần làm việc thì làm việc, lúc cần thư giãn thì phải thư giãn."},{"hanzi":"是的，现在我周末常来郊区，在好山好水好风景中放松自己。","pinyin":"Shì de, xiànzài wǒ zhōumò cháng lái jiāoqū, zài hǎo shān hǎo shuǐ hǎo fēngjǐng zhōng fàngsōng zìjǐ.","speaker":"杨同乐","vi":"Phải đấy, bây giờ cuối tuần anh thường đến ngoại ô, thư giãn bản thân giữa núi non, sông nước và phong cảnh tươi đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Lạc nói \"所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯\" (nên tôi đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, sức khỏe cũng bật đèn đỏ), nên nguyên nhân là do anh tham gia nhiều dự án, thường xuyên tăng ca và thức khuya.","options":["因为他平时工作太轻松，很少运动","因为他参加了很多项目，经常加班、熬夜","因为他周末经常去郊区，太累了","因为他在公司里和同事相处得不好"],"q":"以前杨同乐的身体为什么亮起了红灯？"},{"answerIdx":0,"explanation":"Trong bài, Dương Đồng Lạc chia sẻ \"我发现暂停下来、好好休息之后，我能把工作做得更快更好\" (Tôi phát hiện ra sau khi tạm dừng lại và nghỉ ngơi đàng hoàng, tôi có thể làm việc nhanh hơn và tốt hơn), nên đáp án đúng là anh ấy có thể làm việc nhanh hơn và tốt hơn.","options":["他能把工作做得更快更好","他的工作变得比以前更慢了","他再也不用去公司上班了","公司给他安排了更多的项目"],"q":"后来不再接那么多项目并好好休息以后，杨同乐的工作有什么变化？"}],"scene":"周末，李文、杨同乐等人去郊区游玩。","sceneVi":"Cuối tuần, Lý Văn, Dương Đồng Lạc và mọi người đi ngoại ô dạo chơi."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"以前杨同乐总觉得自己年轻，就应该多学多干、积累经验。","pinyin":"Yǐqián Yáng Tónglè zǒng juéde zìjǐ niánqīng, jiù yīnggāi duō xué duō gàn, jīlěi jīngyàn.","speaker":"Đoạn văn","vi":"Trước đây Dương Đồng Lạc luôn nghĩ mình còn trẻ thì nên học nhiều làm nhiều, tích lũy kinh nghiệm."},{"hanzi":"很多年轻人和他想法一样。","pinyin":"Hěn duō niánqīngrén hé tā xiǎngfǎ yíyàng.","speaker":"Đoạn văn","vi":"Rất nhiều người trẻ cũng có suy nghĩ giống như anh ấy."},{"hanzi":"但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响。","pinyin":"Dànshì, yóuyú gōngzuò jǐnzhāng, tāmen jīngcháng jiābān, áoyè, xiūxi bú gòu, jiéguǒ gōngzuò xiàolǜ xiàjiàng, jiànkāng yě shòudào le yǐngxiǎng.","speaker":"Đoạn văn","vi":"Thế nhưng, do công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất công việc giảm sút và sức khỏe cũng bị ảnh hưởng."},{"hanzi":"现在越来越多的人认识到，跟一直加班相比，休息好了再工作，效率更高。","pinyin":"Xiànzài yuèláiyuè duō de rén rènshì dào, gēn yìzhí jiābān xiāngbǐ, xiūxi hǎo le zài gōngzuò, xiàolǜ gèng gāo.","speaker":"Đoạn văn","vi":"Hiện nay ngày càng có nhiều người nhận ra rằng, so với việc liên tục tăng ca thì nghỉ ngơi đầy đủ rồi mới làm việc sẽ đạt hiệu suất cao hơn."},{"hanzi":"因此，很多人开始做出改变，提醒自己减轻压力、多多放松。","pinyin":"Yīncǐ, hěn duō rén kāishǐ zuòchū gǎibiàn, tíxǐng zìjǐ jiǎnqīng yālì, duōduō fàngsōng.","speaker":"Đoạn văn","vi":"Vì vậy, nhiều người bắt đầu thay đổi, tự nhắc nhở bản thân giảm bớt áp lực và thư giãn nhiều hơn."},{"hanzi":"比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书。","pinyin":"Bǐrú, Yáng Tónglè zhōumò shí huòzhě yǔ péngyoumen qù jiāoqū yóuwán, zài dàzìrán měilì de jǐngsè zhōng hǎohāo fàngsōng zìjǐ; huòzhě jiù zài jiālǐ ān'ānjìngjìng de kànkan shū.","speaker":"Đoạn văn","vi":"Ví dụ, vào cuối tuần Dương Đồng Lạc hoặc là cùng bạn bè đi ngoại ô dạo chơi, thư giãn thật tốt giữa khung cảnh thiên nhiên tươi đẹp; hoặc là ở nhà đọc sách một cách yên tĩnh."},{"hanzi":"休息好了，再回去上班时，心情愉快，工作效率也更高。","pinyin":"Xiūxi hǎo le, zài huíqù shàngbān shí, xīnqíng yúkuài, gōngzuò xiàolǜ yě gèng gāo.","speaker":"Đoạn văn","vi":"Nghỉ ngơi đầy đủ rồi, khi quay lại đi làm, tâm trạng vui vẻ mà hiệu suất công việc cũng cao hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响\" (Nhưng do công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất công việc giảm sút, sức khỏe cũng bị ảnh hưởng), nên hậu quả là hiệu suất công việc giảm và sức khỏe bị ảnh hưởng.","options":["经验很快增加，心情越来越好","工作效率下降，健康也受到影响","每个人都能更快地完成所有工作","周末会有更多时间和朋友去郊区"],"q":"根据课文，年轻人经常加班、熬夜、休息不够会带来什么结果？"},{"answerIdx":1,"explanation":"Trong bài có câu \"比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书\" (Ví dụ, cuối tuần Dương Đồng Lạc hoặc đi chơi ngoại ô với bạn bè để thư giãn giữa cảnh đẹp thiên nhiên; hoặc ở nhà yên tĩnh đọc sách), nên đáp án đúng là đi chơi ngoại ô cùng bạn bè hoặc yên tĩnh đọc sách ở nhà.","options":["继续在公司加班，或者准备下周的项目","和朋友去郊区游玩，或者在家里安安静静地看书","每天都在家里睡觉，哪里都不去","一个人坐飞机去其他城市旅游"],"q":"杨同乐周末通常怎样放松自己？"}],"scene":"学会放松","sceneVi":"Học cách thư giãn"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"一到周末，很多人都喜欢外出游玩。","pinyin":"Yí dào zhōumò, hěn duō rén dōu xǐhuan wàichū yóuwán.","speaker":"Đoạn văn","vi":"Cứ đến cuối tuần, rất nhiều người đều thích ra ngoài đi chơi."},{"hanzi":"你一般去哪里呢？","pinyin":"Nǐ yìbān qù nǎlǐ ne?","speaker":"Đoạn văn","vi":"Bạn thường đi đâu thế?"},{"hanzi":"我生活在中国的首都——北京。","pinyin":"Wǒ shēnghuó zài Zhōngguó de shǒudū——Běijīng.","speaker":"Đoạn văn","vi":"Tôi sống ở Bắc Kinh — thủ đô của Trung Quốc."},{"hanzi":"在北京，周末的时候，有人会在市区公园走走，看看眼前的美景；有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化。","pinyin":"Zài Běijīng, zhōumò de shíhou, yǒurén huì zài shìqū gōngyuán zǒuzou, kànkan yǎnqián de měijǐng; yǒurén xǐhuan qù cānguān Chángchéng, Gùgōng děng yǒumíng de jǐngdiǎn, fàngsōng xīnqíng de tóngshí, yě néng liǎojiě lìshǐ wénhuà.","speaker":"Đoạn văn","vi":"Ở Bắc Kinh, vào cuối tuần, có người sẽ đi dạo trong công viên nội thành, ngắm nhìn cảnh đẹp trước mắt; có người thích đi tham quan các danh lam thắng cảnh nổi tiếng như Vạn Lý Trường Thành, Cố Cung, vừa thư giãn tâm trạng lại vừa có thể tìm hiểu văn hóa lịch sử."},{"hanzi":"北京交通很方便，所以我和家人更爱乘坐公交车去郊区，偶尔也会自己开车。","pinyin":"Běijīng jiāotōng hěn fāngbiàn, suǒyǐ wǒ hé jiārén gèng ài chéngzuò gōngjiāochē qù jiāoqū, ǒu'ěr yě huì zìjǐ kāichē.","speaker":"Đoạn văn","vi":"Giao thông ở Bắc Kinh rất thuận tiện, vì vậy tôi và gia đình thích đi xe buýt ra vùng ngoại ô hơn, thỉnh thoảng cũng tự lái xe."},{"hanzi":"郊区有山有水，还有很多农家乐，吃、玩、住都十分方便。","pinyin":"Jiāoqū yǒu shān yǒu shuǐ, hái yǒu hěn duō nóngjiālè, chī, wán, zhù dōu shífēn fāngbiàn.","speaker":"Đoạn văn","vi":"Vùng ngoại ô có núi có sông, còn có rất nhiều khu du lịch nhà nông (nông gia lạc), ăn uống, vui chơi, nghỉ ngơi đều vô cùng tiện lợi."},{"hanzi":"在我看来，不管去哪里玩，实际上都是为了放松。","pinyin":"Zài wǒ kànlái, bùguǎn qù nǎlǐ wán, shíjìshang dōu shì wèile fàngsōng.","speaker":"Đoạn văn","vi":"Theo tôi thấy, bất kể đi chơi ở đâu, thực chất đều là để thư giãn."},{"hanzi":"也可以说，只要能放松，去哪儿都合适。","pinyin":"Yě kěyǐ shuō, zhǐyào néng fàngsōng, qù nǎr dōu héshì.","speaker":"Đoạn văn","vi":"Cũng có thể nói rằng, chỉ cần có thể thư giãn được thì đi đâu cũng đều thích hợp cả."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化\" (Có người thích đi tham quan các danh thắng nổi tiếng như Trường Thành, Cố Cung, vừa thư giãn tâm trạng vừa có thể tìm hiểu lịch sử văn hóa), nên lợi ích là vừa thư giãn vừa tìm hiểu được lịch sử văn hóa.","options":["既可以放松心情，又能了解历史文化","可以住进郊区的农家乐里吃住","不用买票，而且比市区公园更近","自己开车直接在景点里面逛"],"q":"在北京，人们周末去参观长城、故宫等景点有什么好处？"},{"answerIdx":2,"explanation":"Trong bài, tác giả kết luận \"在我看来，不管去哪里玩，实际上都是为了放松。也可以说，只要能放松，去哪儿都合适\" (Theo tôi, bất kể đi chơi ở đâu, thực ra đều là để thư giãn. Cũng có thể nói, chỉ cần có thể thư giãn thì đi đâu cũng hợp), nên đáp án đúng là chỉ cần giúp bản thân thư giãn thì đi đâu cũng phù hợp.","options":["必须去有山有水的郊区农家乐","一定要去北京最有名的历史景点","只要能让自己放松，去哪儿都合适","最好是不用坐公交车就能到的地方"],"q":"在作者看来，去哪里游玩才是最合适的？"}],"scene":"去哪儿放松好","sceneVi":"Đi đâu thư giãn thì tốt"}],"hsk4a-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，给你的，祝你生日快乐！","pinyin":"Jiāyuè, gěi nǐ de, zhù nǐ shēngrì kuàilè!","speaker":"李文","vi":"Gia Nguyệt, tặng em này, chúc em sinh nhật vui vẻ!"},{"hanzi":"啊，好漂亮的花！还有巧克力！你怎么知道我喜欢这个巧克力？","pinyin":"A, hǎo piàoliang de huā! Hái yǒu qiǎokèlì! Nǐ zěnme zhīdào wǒ xǐhuan zhège qiǎokèlì?","speaker":"白家月","vi":"Ồ, hoa đẹp quá! Còn có cả sô-cô-la nữa! Sao anh biết em thích loại sô-cô-la này vậy?"},{"hanzi":"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。","pinyin":"Shàngcì zánmen qù chāoshì, kàn nǐ ná qǐlái kàn le kàn yòu fàng xià le, wǒ jiù jìzhù le.","speaker":"李文","vi":"Lần trước chúng ta đi siêu thị, thấy em cầm lên xem rồi lại đặt xuống, anh liền nhớ kỹ luôn."},{"hanzi":"好感动！我不说你也懂我在想什么，你真是细心又浪漫。其实刚认识不久，你的幽默与耐心就很吸引我，不过我当时也只把你当普通朋友。如果你没有一直找我聊天儿，我们可能就错过了。","pinyin":"Hǎo gǎndòng! Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme, nǐ zhēn shì xìxīn yòu làngmàn. Qíshí gāng rènshi bùjiǔ, nǐ de yōumò yǔ nàixīn jiù hěn xīyǐn wǒ, búguò wǒ dāngshí yě zhǐ bǎ nǐ dāng pǔtōng péngyou. Rúguǒ nǐ méiyǒu yìzhí zhǎo wǒ liáotiānr, wǒmen kěnéng jiù cuòguò le.","speaker":"白家月","vi":"Cảm động quá! Em không nói anh cũng hiểu em đang nghĩ gì, anh đúng là vừa chu đáo lại vừa lãng mạn. Thật ra hồi mới quen chưa lâu, sự hài hước và kiên nhẫn của anh đã rất thu hút em rồi, nhưng lúc đó em cũng chỉ coi anh là bạn bình thường. Nếu anh không luôn chủ động tìm em trò chuyện, có lẽ chúng ta đã bỏ lỡ nhau rồi."},{"hanzi":"我终于遇见了对的人，哪能错过呢？","pinyin":"Wǒ zhōngyú yùjiàn le duì de rén, nǎ néng cuòguò ne?","speaker":"李文","vi":"Anh cuối cùng cũng gặp được đúng người rồi, sao có thể bỏ lỡ được chứ?"},{"hanzi":"遇见你，我也觉得很幸运。","pinyin":"Yùjiàn nǐ, wǒ yě juéde hěn xìngyùn.","speaker":"白家月","vi":"Gặp được anh, em cũng cảm thấy rất may mắn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi nhận quà, Bạch Gia Nguyệt đã thốt lên \"啊，好漂亮的花！还有巧克力！\" (Ôi, hoa đẹp quá! Lại còn có sô-cô-la nữa!), nên đáp án đúng là hoa và sô-cô-la (花和巧克力).","options":["衣服和帽子","花和巧克力","蛋糕和水果","书和咖啡"],"q":"白家月过生日时，李文送了她什么礼物？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn giải thích \"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。\" (Lần trước hai ta đi siêu thị, thấy em cầm lên xem rồi lại đặt xuống, nên anh đã nhớ kỹ.), nên đáp án đúng là anh ấy đã để ý thấy trong lần đi siêu thị trước.","options":["白家月的朋友告诉他的","白家月发微信跟他说过","他上次去超市时注意到的","服务员向他推荐的"],"q":"李文是怎么知道白家月喜欢那种巧克力的？"}],"scene":"在餐馆里，李文给白家月过生日。","sceneVi":"Ở trong nhà hàng, Lý Văn tổ chức sinh nhật cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"看到一飞和同乐结婚后这么幸福，我这个介绍人也特别开心。","pinyin":"Kàndào Yīfēi hé Tónglè jiéhūn hòu zhème xìngfú, wǒ zhège jièshàorén yě tèbié kāixīn.","speaker":"王一雪","vi":"Thấy Nhất Phi và Đồng Lạc sau khi kết hôn hạnh phúc như vậy, người làm mối như em cũng thấy đặc biệt vui mừng."},{"hanzi":"是啊，同乐是你的好朋友，一飞是你妹妹，你都很了解。","pinyin":"Shì a, Tónglè shì nǐ de hǎo péngyou, Yīfēi shì nǐ mèimei, nǐ dōu hěn liǎojiě.","speaker":"刘明","vi":"Đúng vậy, Đồng Lạc là bạn tốt của em, Nhất Phi là em gái em, em đều rất hiểu cả hai."},{"hanzi":"嗯，他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。","pinyin":"Ng, tāmen jǐnguǎn xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào. Tèbié shì Tónglè rén hǎo, xìnggé yě hǎo, hěn yǒu zérèngǎn.","speaker":"王一雪","vi":"Ừ, tuy tính cách họ khác nhau, nhưng lại có rất nhiều sở thích chung. Đặc biệt là Đồng Lạc người tốt, tính tình cũng tốt, lại rất có tinh thần trách nhiệm."},{"hanzi":"是的，一飞也算在对的时间遇到了对的人。后边的路还很长，希望他们能一直相互理解、相互支持。","pinyin":"Shì de, Yīfēi yě suàn zài duì de shíjiān yùdào le duì de rén. Hòubian de lù hái hěn cháng, xīwàng tāmen néng yìzhí xiānghù lǐjiě, xiānghù zhīchí.","speaker":"刘明","vi":"Phải đấy, Nhất Phi cũng coi như đã gặp được đúng người vào đúng thời điểm. Chặng đường phía sau còn rất dài, hy vọng họ có thể luôn thấu hiểu và ủng hộ lẫn nhau."},{"hanzi":"我了解同乐，更了解一飞，相信他们会一直走下去的。","pinyin":"Wǒ liǎojiě Tónglè, gèng liǎojiě Yīfēi, xiāngxìn tāmen huì yìzhí zǒu xiàqù de.","speaker":"王一雪","vi":"Em hiểu Đồng Lạc, càng hiểu Nhất Phi hơn, tin rằng họ sẽ đi cùng nhau đến suốt đời."},{"hanzi":"祝他们越来越幸福。","pinyin":"Zhù tāmen yuèláiyuè xìngfú.","speaker":"刘明","vi":"Chúc họ ngày càng hạnh phúc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。\" (Tuy tính cách của họ khác nhau, nhưng có rất nhiều sở thích chung. Đặc biệt là Đồng Lạc người tốt, tính tình cũng tốt, rất có tinh thần trách nhiệm.), nên đáp án đúng là họ có nhiều sở thích chung và Đồng Lạc là người tốt, có trách nhiệm.","options":["他们性格完全一样，而且住得很近","他们有很多共同爱好，而且同乐人好、有责任感","他们从小一起长大，非常了解彼此","他们在同一家公司工作，天天见面"],"q":"在王一雪看来，一飞和同乐为什么很合适？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Minh nói \"后边的路还很长，希望他们能一直相互理解、相互支持。\" (Chặng đường phía trước còn rất dài, hy vọng họ có thể luôn thấu hiểu và ủng hộ lẫn nhau.), nên đáp án đúng là hy vọng họ luôn thấu hiểu và ủng hộ lẫn nhau.","options":["希望他们以后能经常出去旅游","希望他们早点儿买一套大房子","希望他们能一起换一份更好的工作","希望他们一直相互理解、相互支持"],"q":"对于一飞和同乐以后的婚姻生活，刘明有什么希望？"}],"scene":"在家里，王一雪和刘明谈论王一飞和杨同乐的婚姻。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh bàn luận về cuộc hôn nhân của Vương Nhất Phi và Dương Đồng Lạc."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"王一雪比杨同乐更早进入公司。","pinyin":"Wáng Yīxuě bǐ Yáng Tónglè gèng zǎo jìnrù gōngsī.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết vào công ty sớm hơn Dương Đồng Lạc."},{"hanzi":"杨同乐刚来不久，王一雪对他印象就非常好：人很实在，性格阳光，工作负责，表现积极……","pinyin":"Yáng Tónglè gāng lái bùjiǔ, Wáng Yīxuě duì tā yìnxiàng jiù fēicháng hǎo: rén hěn shízài, xìnggé yángguāng, gōngzuò fùzé, biǎoxiàn jījí……","speaker":"Đoạn văn","vi":"Dương Đồng Lạc mới đến chưa lâu, Vương Nhất Tuyết đã có ấn tượng rất tốt về anh ấy: con người chân thật, tính cách cởi mở tươi sáng, làm việc có trách nhiệm, biểu hiện tích cực..."},{"hanzi":"后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。","pinyin":"Hòulái tāmen yìqǐ chū le cì chāi, cǐcì chūchāi, ràng liǎng rén shúxī le qǐlái, cóngcǐ chéng le hǎo péngyou.","speaker":"Đoạn văn","vi":"Sau đó họ cùng nhau đi công tác một chuyến, chuyến công tác này đã giúp hai người thân thiết hơn, từ đó trở thành bạn tốt."},{"hanzi":"一次聊天儿时，王一雪了解到杨同乐还没女朋友，正好自己的妹妹王一飞也没有男朋友，于是王一雪就把王一飞介绍给了他。","pinyin":"Yícì liáotiānr shí, Wáng Yīxuě liǎojiě dào Yáng Tónglè hái méi nǚpéngyou, zhènghǎo zìjǐ de mèimei Wáng Yīfēi yě méiyǒu nánpéngyou, yúshì Wáng Yīxuě jiù bǎ Wáng Yīfēi jièshào gěi le tā.","speaker":"Đoạn văn","vi":"Một lần trò chuyện, Vương Nhất Tuyết biết được Dương Đồng Lạc vẫn chưa có bạn gái, trùng hợp em gái mình là Vương Nhất Phi cũng chưa có bạn trai, thế là Vương Nhất Tuyết bèn giới thiệu Vương Nhất Phi cho anh ấy."},{"hanzi":"杨同乐和王一飞认识后，很聊得来，两人之间慢慢产生了爱情，最后成了夫妻。","pinyin":"Yáng Tónglè hé Wáng Yīfēi rènshi hòu, hěn liáodelái, liǎng rén zhījiān mànmàn chǎnshēng le àiqíng, zuìhòu chéng le fūqī.","speaker":"Đoạn văn","vi":"Sau khi quen nhau, Dương Đồng Lạc và Vương Nhất Phi nói chuyện rất hợp, giữa hai người dần nảy sinh tình yêu, cuối cùng trở thành vợ chồng."},{"hanzi":"杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。","pinyin":"Yáng Tónglè shuō zìjǐ hěn xìngyùn, hé Wáng Yīxuě zhè fèn tóngshì jiān de yǒuqíng, gěi tā dàilái le měihǎo de àiqíng.","speaker":"Đoạn văn","vi":"Dương Đồng Lạc nói mình rất may mắn, tình bạn đồng nghiệp với Vương Nhất Tuyết đã mang lại cho anh ấy một tình yêu đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。\" (Sau này họ cùng đi công tác một chuyến, chuyến công tác này đã giúp hai người trở nên thân thiết và từ đó thành bạn tốt.), nên đáp án đúng là sau khi họ cùng đi công tác.","options":["他们一起参加大学同学聚会的时候","他们一起出差以后","王一飞介绍他们认识以后","杨同乐刚搬家到王一雪家附近时"],"q":"王一雪和杨同乐是在什么情况下熟悉起来的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。\" (Dương Đồng Lạc nói mình rất may mắn, tình bạn đồng nghiệp với Vương Nhất Tuyết đã mang lại cho anh ấy một tình yêu đẹp.), nên đáp án đúng là tình bạn với Vương Nhất Tuyết đã mang lại cho anh ấy tình yêu đẹp.","options":["因为他刚进公司就得到了很高的工资","因为他经常能去不同的城市出差","因为和王一雪的友情给他带来了美好的爱情","因为他不用找工作就认识了王一雪"],"q":"杨同乐为什么觉得自己很幸运？"}],"scene":"杨同乐的双份幸运","sceneVi":"Niềm may mắn nhân đôi của Dương Đồng Lạc"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"李文在校园里遇见白家月，从此，他们的人生变得更加精彩；王一飞和杨同乐通过王一雪介绍认识后，感情越来越深，最后两人幸福地走到了一起。","pinyin":"Lǐ Wén zài xiàoyuán lǐ yùjiàn Bái Jiāyuè, cóngcǐ, tāmen de rénshēng biànde gèngjiā jīngcǎi; Wáng Yīfēi hé Yáng Tónglè tōngguò Wáng Yīxuě jièshào rènshi hòu, gǎnqíng yuèláiyuè shēn, zuìhòu liǎng rén xìngfú de zǒudào le yìqǐ.","speaker":"Đoạn văn","vi":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường, từ đó cuộc đời họ trở nên rực rỡ hơn; Vương Nhất Phi và Dương Đồng Lạc sau khi quen nhau qua sự giới thiệu của Vương Nhất Tuyết, tình cảm ngày càng sâu đậm, cuối cùng hai người đã hạnh phúc đến với nhau."},{"hanzi":"在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。","pinyin":"Zài wǒ kànlái, yùjiàn àiqíng de fāngshì bìng bú zhòngyào, zhòngyào de shì zài héshì de shíjiān yùdào le héshì de rén.","speaker":"Đoạn văn","vi":"Theo tôi, cách thức gặp được tình yêu không hề quan trọng, điều quan trọng là gặp được đúng người vào đúng thời điểm."},{"hanzi":"遇见你，刚刚好。","pinyin":"Yùjiàn nǐ, gānggānghǎo.","speaker":"Đoạn văn","vi":"Gặp được bạn, vừa vặn đúng lúc."},{"hanzi":"不过美好的遇见只是爱的开始，爱更需要经营。","pinyin":"Búguò měihǎo de yùjiàn zhǐ shì ài de kāishǐ, ài gèng xūyào jīngyíng.","speaker":"Đoạn văn","vi":"Tuy nhiên, cuộc gặp gỡ tốt đẹp chỉ là khởi đầu của tình yêu, tình yêu càng cần phải được vun đắp."},{"hanzi":"在一段感情中，两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。","pinyin":"Zài yí duàn gǎnqíng zhōng, liǎng gè rén yào duō guānzhù duìfāng de gǎnshòu, yóuqí shì jiéhūn hòu, gèng yào gòngtóng jīngyíng hǎo jiātíng, rìzi cái néng yuè guò yuè hǎo.","speaker":"Đoạn văn","vi":"Trong một mối quan hệ tình cảm, hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn, càng phải cùng nhau vun vén gia đình thật tốt thì cuộc sống mới ngày càng tốt đẹp hơn được."},{"hanzi":"爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":"Ài, cónglái dōu shì xiānghù zūnzhòng, lǐjiě yǔ zhīchí, búshì ma?","speaker":"Đoạn văn","vi":"Tình yêu từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không nào?"}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。\" (Theo tôi thấy, cách gặp được tình yêu không quan trọng, điều quan trọng là gặp đúng người vào đúng thời điểm.), nên đáp án đúng là gặp đúng người vào đúng thời điểm.","options":["遇见爱情的方式一定要很浪漫","必须是在校园里认识的","一定要通过好朋友的介绍","在合适的时间遇到合适的人"],"q":"在作者看来，遇见爱情时最重要的是什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。\" (Hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn càng phải cùng nhau vun đắp gia đình, cuộc sống mới ngày càng tốt đẹp hơn.), nên đáp án đúng là quan tâm nhiều hơn đến cảm nhận của nhau và cùng nhau vun đắp gia đình.","options":["多关注对方感受，共同经营好家庭","每天都给对方买很贵的礼物","遇到问题时不要告诉对方","尽量减少见面，各自忙自己的事"],"q":"为了让感情和婚姻生活越来越好，两个人应该怎么做？"}],"scene":"爱更需要经营","sceneVi":"Tình yêu càng cần sự vun đắp"}],"hsk4a-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你看，这个小伙子从广州去哈尔滨出差，没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。","pinyin":"Nǐ kàn, zhège xiǎohuǒzi cóng Guǎngzhōu qù Hā'ěrbīn chūchāi, méi xiǎngdào Hā'ěrbīn de qìwēn jiàngdào le língxià èrshí jǐ dù, bǎ tā dòng huài le.","speaker":"刘明","vi":"Em xem này, chàng trai này đi công tác từ Quảng Châu đến Cáp Nhĩ Tân, không ngờ nhiệt độ ở Cáp Nhĩ Tân giảm xuống âm hơn hai mươi độ, làm anh ấy lạnh cóng luôn."},{"hanzi":"他一定后悔自己穿少了吧？","pinyin":"Tā yídìng hòuhuǐ zìjǐ chuān shǎo le ba?","speaker":"王一雪","vi":"Chắc chắn anh ấy hối hận vì mình mặc ít quá rồi nhỉ?"},{"hanzi":"是啊，这就叫南方不懂北方的冷。","pinyin":"Shì a, zhè jiù jiào nánfāng bù dǒng běifāng de lěng.","speaker":"刘明","vi":"Đúng vậy, thế này gọi là miền Nam không hiểu cái lạnh của miền Bắc."},{"hanzi":"就是呢，冬天北方和南方的温度差别还是很大的。","pinyin":"Jiùshì ne, dōngtiān běifāng hé nánfāng de wēndù chābié háishì hěn dà de.","speaker":"王一雪","vi":"Đúng thế đấy, mùa đông sự chênh lệch nhiệt độ giữa miền Bắc và miền Nam vẫn rất lớn."},{"hanzi":"所以冬天来北方，尤其是东北，一定要提前查好目的地的天气，看看下不下雪，气温怎么样。","pinyin":"Suǒyǐ dōngtiān lái běifāng, yóuqí shì Dōngběi, yídìng yào tíqián chá hǎo mùdìdì de tiānqì, kànkan xià bu xiàxuě, qìwēn zěnmeyàng.","speaker":"刘明","vi":"Vì vậy mùa đông đến miền Bắc, đặc biệt là vùng Đông Bắc, nhất định phải tra trước thời tiết nơi đến, xem có tuyết rơi không, nhiệt độ thế nào."},{"hanzi":"对。更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":"Duì. Gèng zhòngyào de shì, shuō shénme yě děi chuān shang hòu yìdiǎnr de yīfu.","speaker":"王一雪","vi":"Đúng rồi. Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói \"没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。\" (Không ngờ nhiệt độ ở Cáp Nhĩ Tân giảm xuống hơn âm hai mươi độ, làm cậu ấy lạnh cóng.), nên đáp án đúng là hơn âm hai mươi độ (零下二十几度).","options":["零上二十几度","零下十几度","零下二十几度","零度左右"],"q":"那个小伙子去哈尔滨出差时，那里的气温降到了多少度？"},{"answerIdx":1,"explanation":"Trong bài, Lưu Minh khuyên \"一定要提前查好目的地的天气\" (Nhất định phải xem trước thời tiết nơi đến) và Vương Nhất Tuyết bổ sung \"更重要的是，说什么也得穿上厚一点儿的衣服。\" (Quan trọng hơn là thế nào cũng phải mặc quần áo dày một chút.), nên đáp án đúng là kiểm tra thời tiết trước và mặc quần áo dày hơn.","options":["不用看天气预报，带一把伞就行","提前查好天气，一定要穿厚一点儿的衣服","尽量坐火车去，不要坐飞机","到了北方以后再去买薄衣服"],"q":"对于冬天去北方的人，刘明和王一雪提出了什么建议？"}],"scene":"在家里，刘明和王一雪说他在网上看到的一条信息。","sceneVi":"Ở nhà, Lưu Minh kể với Vương Nhất Tuyết về một mẩu tin anh ấy đọc được trên mạng."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"寒假你们打算做什么呢？","pinyin":"Hánjià nǐmen dǎsuàn zuò shénme ne?","speaker":"王一飞","vi":"Kỳ nghỉ đông các cậu định làm gì thế?"},{"hanzi":"我们刚刚还说呢，家月春节时要去广州，我计划去哈尔滨。","pinyin":"Wǒmen gānggāng hái shuō ne, Jiāyuè Chūnjié shí yào qù Guǎngzhōu, wǒ jìhuà qù Hā'ěrbīn.","speaker":"陈天中","vi":"Bọn mình vừa mới nói xong đấy, dịp Tết Gia Nguyệt sẽ đi Quảng Châu, còn mình dự định đi Cáp Nhĩ Tân."},{"hanzi":"那时候广州暖和，但哈尔滨特别冷，气温一般都低于零下十摄氏度甚至零下二十摄氏度，这么低的温度你受不了吧？","pinyin":"Nà shíhou Guǎngzhōu nuǎnhuo, dàn Hā'ěrbīn tèbié lěng, qìwēn yìbān dōu dīyú língxià shí shèshìdù shènzhì língxià èrshí shèshìdù, zhème dī de wēndù nǐ shòubuliǎo ba?","speaker":"王一飞","vi":"Lúc đó Quảng Châu ấm áp, nhưng Cáp Nhĩ Tân đặc biệt lạnh, nhiệt độ thường dưới âm mười độ C thậm chí âm hai mươi độ C, nhiệt độ thấp như vậy cậu chịu không nổi đâu nhỉ?"},{"hanzi":"没问题，受得了，我有的是厚衣服。我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。","pinyin":"Méi wèntí, shòudeliǎo, wǒ yǒudeshì hòu yīfu. Wǒ qù Hā'ěrbīn zhǔyào shì xiǎng kàn xuě, tīngshuō Chūnjié shí nàlǐ huì jǔbàn hěn duō huódòng.","speaker":"陈天中","vi":"Không sao đâu, chịu được mà, mình có khối quần áo dày. Mình đi Cáp Nhĩ Tân chủ yếu là muốn ngắm tuyết, nghe nói dịp Tết ở đó sẽ tổ chức rất nhiều hoạt động."},{"hanzi":"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。","pinyin":"Wǒ xiǎng zài Guǎngzhōu guònián, nàlǐ dōngtiān bǐjiào nuǎnhuo. Érqiě wǒ xǐhuan kàn huā, tīngshuō Guǎngzhōu de xiānhuā shìchǎng hěn yǒumíng, lǐmiàn yǒu gèzhǒng zhíwù.","speaker":"白家月","vi":"Mình muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa mình thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng, bên trong có đủ các loại thực vật."},{"hanzi":"真不错！听你们这么一说，我也想外出旅游了。","pinyin":"Zhēn búcuò! Tīng nǐmen zhème yì shuō, wǒ yě xiǎng wàichū lǚyóu le.","speaker":"王一飞","vi":"Tuyệt thật đấy! Nghe các cậu nói thế, mình cũng muốn ra ngoài đi du lịch rồi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Trần Thiên Trung nói \"我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。\" (Tôi đi Cáp Nhĩ Tân chủ yếu là muốn ngắm tuyết, nghe nói dịp Tết ở đó sẽ tổ chức nhiều hoạt động.), nên đáp án đúng là đến đó ngắm tuyết và tham gia hoạt động.","options":["去那里看雪和参加活动","去那里买很多厚衣服","去那里逛有名的鲜花市场","因为那里冬天比广州更暖和"],"q":"陈天中计划春节去哈尔滨主要是为了什么？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。\" (Tôi muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa tôi thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng...), nên đáp án đúng là vì mùa đông ở đó ấm áp và cô ấy thích ngắm hoa.","options":["因为她想去广州出差工作","因为那里冬天较暖和，而且她喜欢看花","因为广州的冬天经常下大雪","因为她的好朋友住在哈尔滨"],"q":"白家月为什么想在广州过年？"}],"scene":"在校园里，王一飞下课后遇到陈天中和白家月。","sceneVi":"Trong khuôn viên trường, Vương Nhất Phi sau giờ tan học gặp Trần Thiên Trung và Bạch Gia Nguyệt."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"广州和哈尔滨，一个在南方，一个在北方，两个城市之间的距离有三千多公里，气候也大不相同。","pinyin":"Guǎngzhōu hé Hā'ěrbīn, yígè zài nánfāng, yígè zài běifāng, liǎng gè chéngshì zhījiān de jùlí yǒu sānqiān duō gōnglǐ, qìhòu yě dà bù xiāngtóng.","speaker":"Đoạn văn","vi":"Quảng Châu và Cáp Nhĩ Tân, một thành phố ở miền Nam, một thành phố ở miền Bắc, khoảng cách giữa hai thành phố hơn ba nghìn ki-lô-mét, khí hậu cũng khác nhau rất nhiều."},{"hanzi":"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","pinyin":"Guǎngzhōu jīběnshang méiyǒu dōngtiān, ér Hā'ěrbīn de dōngtiān yìbān huì cóng shíyuè kāishǐ, dào dì-èr nián de sān sì yuè cái jiéshù.","speaker":"Đoạn văn","vi":"Quảng Châu về cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng mười, đến tháng ba hoặc tháng tư năm sau mới kết thúc."},{"hanzi":"广州四季开满鲜花，所以又叫“花城”；哈尔滨冬天冰雪多，所以也叫“冰城”。","pinyin":"Guǎngzhōu sìjì kāi mǎn xiānhuā, suǒyǐ yòu jiào “Huāchéng”; Hā'ěrbīn dōngtiān bīngxuě duō, suǒyǐ yě jiào “Bīngchéng”.","speaker":"Đoạn văn","vi":"Quảng Châu bốn mùa nở đầy hoa tươi nên còn được gọi là “Hoa Thành”; Cáp Nhĩ Tân mùa đông nhiều băng tuyết nên cũng được gọi là “Băng Thành”."},{"hanzi":"此外，两地的方言也不一样。","pinyin":"Cǐwài, liǎng dì de fāngyán yě bù yíyàng.","speaker":"Đoạn văn","vi":"Ngoài ra, phương ngữ của hai nơi cũng không giống nhau."},{"hanzi":"哈尔滨方言和普通话听起来比较像，而广州方言和普通话差别较大。","pinyin":"Hā'ěrbīn fāngyán hé pǔtōnghuà tīng qǐlái bǐjiào xiàng, ér Guǎngzhōu fāngyán hé pǔtōnghuà chābié jiào dà.","speaker":"Đoạn văn","vi":"Phương ngữ Cáp Nhĩ Tân và tiếng phổ thông nghe khá giống nhau, còn phương ngữ Quảng Châu và tiếng phổ thông có sự khác biệt khá lớn."},{"hanzi":"如果广州人和哈尔滨人都只使用自己的方言，那么交流就很困难，甚至还可能引起误会。","pinyin":"Rúguǒ Guǎngzhōurén hé Hā'ěrbīnrén dōu zhǐ shǐyòng zìjǐ de fāngyán, nàme jiāoliú jiù hěn kùnnan, shènzhì hái kěnéng yǐnqǐ wùhuì.","speaker":"Đoạn văn","vi":"Nếu người Quảng Châu và người Cáp Nhĩ Tân đều chỉ sử dụng phương ngữ của mình, thì việc giao tiếp sẽ rất khó khăn, thậm chí còn có thể gây ra hiểu lầm."},{"hanzi":"其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。","pinyin":"Qíshí, Zhōngguó hěn duō dìfang dōu yǒu zìjǐ de fāngyán, suǒyǐ, wèile shùnlì jiāoliú, Zhōngguó rén cóngxiǎo dōu yào xuéxí pǔtōnghuà.","speaker":"Đoạn văn","vi":"Thực ra, rất nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy, để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。\" (Quảng Châu về cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng mười và đến tháng ba, tháng tư năm sau mới kết thúc.), nên đáp án đúng là Quảng Châu cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân rất dài.","options":["广州的冬天从十月开始，非常冷","哈尔滨四季开满鲜花，基本没有冬天","广州基本没有冬天，哈尔滨的冬天很长","两个城市的冬天一样长，冰雪都很多"],"q":"关于广州和哈尔滨的气候，下面哪一项是对的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。\" (Thực ra, nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông.), nên đáp án đúng là vì nhiều nơi có phương ngữ khác nhau, học tiếng phổ thông là để giao tiếp thuận lợi.","options":["因为中国很多地方方言不同，学普通话是为了顺利交流","因为所有地方的方言和普通话都完全一样","因为广州方言和哈尔滨方言都听不懂","因为只有学会普通话才能去北方旅游"],"q":"中国人为什么从小都要学习普通话？"}],"scene":"广州与哈尔滨的不同","sceneVi":"Sự khác biệt giữa Quảng Châu và Cáp Nhĩ Tân"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"亲爱的同学们：","pinyin":"Qīn'ài de tóngxuémen:","speaker":"Đoạn văn","vi":"Các bạn học sinh thân mến:"},{"hanzi":"今年的“世界环境日”，我们再次开展“绿色生活”活动，希望同学们做到：","pinyin":"Jīnnián de “Shìjiè Huánjìng Rì”, wǒmen zàicì kāizhǎn “Lǜsè Shēnghuó” huódòng, xīwàng tóngxuémen zuòdào:","speaker":"Đoạn văn","vi":"Nhân “Ngày Môi trường Thế giới” năm nay, chúng ta một lần nữa phát động hoạt động “Cuộc sống xanh”, mong các bạn học sinh thực hiện được:"},{"hanzi":"一、绿色出行","pinyin":"Yī, lǜsè chūxíng","speaker":"Đoạn văn","vi":"Một, đi lại xanh"},{"hanzi":"绿色一小步，环保一大步。","pinyin":"Lǜsè yì xiǎo bù, huánbǎo yí dà bù.","speaker":"Đoạn văn","vi":"Một bước nhỏ sống xanh, một bước lớn bảo vệ môi trường."},{"hanzi":"根据距离选择绿色交通方式。","pinyin":"Gēnjù jùlí xuǎnzé lǜsè jiāotōng fāngshì.","speaker":"Đoạn văn","vi":"Lựa chọn phương tiện giao thông xanh tùy theo khoảng cách."},{"hanzi":"距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。","pinyin":"Jùlí duǎn shí kěyǐ zǒulù huòzhě qí zìxíngchē, jùlí cháng shí duō chéngzuò gōngjiāochē huòzhě dìtiě.","speaker":"Đoạn văn","vi":"Khi quãng đường ngắn có thể đi bộ hoặc đạp xe đạp, khi quãng đường dài nên đi xe buýt hoặc tàu điện ngầm nhiều hơn."},{"hanzi":"二、拒绝浪费","pinyin":"Èr, jùjué làngfèi","speaker":"Đoạn văn","vi":"Hai, từ chối lãng phí"},{"hanzi":"节约资源，坚持一水多用、人走灯关、餐餐都“光盘”。","pinyin":"Jiéyuē zīyuán, jiānchí yì shuǐ duō yòng, rén zǒu dēng guān, cāncān dōu “guāngpán”.","speaker":"Đoạn văn","vi":"Tiết kiệm tài nguyên, kiên trì dùng nước nhiều lần, người đi tắt đèn, bữa nào cũng ăn sạch đĩa (“đĩa sạch”)."},{"hanzi":"三、垃圾分类","pinyin":"Sān, lājī fēnlèi","speaker":"Đoạn văn","vi":"Ba, phân loại rác thải"},{"hanzi":"积极参加校园、小区环保活动，学习垃圾分类知识，从小事做起，做好垃圾分类。","pinyin":"Jījí cānjiā xiàoyuán, xiǎoqū huánbǎo huódòng, xuéxí lājī fēnlèi zhīshi, cóng xiǎoshì zuòqǐ, zuòhǎo lājī fēnlèi.","speaker":"Đoạn văn","vi":"Tích cực tham gia các hoạt động bảo vệ môi trường ở trường học và khu dân cư, học kiến thức phân loại rác, bắt đầu từ những việc nhỏ để làm tốt việc phân loại rác."},{"hanzi":"保护环境是每一个人的责任。","pinyin":"Bǎohù huánjìng shì měi yígè rén de zérèn.","speaker":"Đoạn văn","vi":"Bảo vệ môi trường là trách nhiệm của mỗi người."},{"hanzi":"同学们，让我们共同努力，让绿色生活成为我们的日常习惯！","pinyin":"Tóngxuémen, ràng wǒmen gòngtóng nǔlì, ràng lǜsè shēnghuó chéngwéi wǒmen de rìcháng xíguàn!","speaker":"Đoạn văn","vi":"Các bạn học sinh ơi, hãy cùng nhau nỗ lực để lối sống xanh trở thành thói quen hằng ngày của chúng ta!"},{"hanzi":"校学生会 2026年6月5日","pinyin":"Xiào xuéshēnghuì 2026 nián 6 yuè 5 rì","speaker":"Đoạn văn","vi":"Hội học sinh trường, ngày 5 tháng 6 năm 2026"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"根据距离选择绿色交通方式。距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。\" (Chọn phương tiện giao thông xanh theo khoảng cách. Khi khoảng cách ngắn có thể đi bộ hoặc đi xe đạp, khi khoảng cách dài nên đi xe buýt hoặc tàu điện ngầm.), nên đáp án đúng là tùy khoảng cách mà chọn đi bộ, đi xe đạp hoặc đi xe buýt, tàu điện ngầm.","options":["每天都只走路，不要坐任何车","不管去哪里都尽量自己开车","根据距离选择走路、骑自行车，或乘坐公交车、地铁","距离长的时候也一定要骑自行车"],"q":"为了做到“绿色出行”，发起书建议同学们怎么做？"},{"answerIdx":3,"explanation":"Trong mục \"二、拒绝浪费\" (Từ chối lãng phí), văn bản chỉ nhắc đến \"坚持一水多用、人走灯关、餐餐都“光盘”\" (kiên trì dùng một nước nhiều việc, người đi tắt đèn, bữa nào cũng ăn sạch đĩa), không hề nhắc đến việc ít mua quần áo mới (\"少买新衣服\").","options":["一水多用","人走灯关","餐餐都“光盘”","少买新衣服"],"q":"下面哪一项在“拒绝浪费”部分没有提到？"}],"scene":"“世界环境日”那天，刘小雪学校学生会发布了一份活动发起书。","sceneVi":"Vào “Ngày Môi trường Thế giới”, Hội học sinh trường của Lưu Tiểu Tuyết đã phát hành một bản phát động hoạt động."}]});
